export interface NewsItem {
  id: string;
  title: string;
  summary: string;
  location?: string;
  sourceUrl?: string;
  date?: string; // Publication date/time
}

export interface DigestData {
  news: NewsItem[];
  hacks: string[];
  facts: string[];
  formattedDigestText: string; // Ready-to-publish text with emojis (Long version)
  formattedShortDigest: string; // Ticker style / Running line (Short version)
  collagePrompt: string;       // Prompt for the main digest image
  collageImage?: string;       // The generated base64 image
}

export interface GeneratedArticle {
  headline: string;
  content: string; // Markdown formatted with H1, H2
  hashtags: string; // Comma separated, NO #
}

export interface GeneratedSocialPost {
  content: string; // Includes # hashtags
}

export interface GeneratedContentPack {
  newsId: string;
  siteArticle: GeneratedArticle;
  telegramPost: GeneratedSocialPost;
  vkPost: GeneratedSocialPost;
  imagePrompts: string[];
  metaDescription: string;
  generatedImages: string[]; // Base64 strings (Strictly 3)
  error?: string; // Optional error message if generation failed for this specific item
}

export enum AppState {
  IDLE = 'IDLE',
  SEARCHING = 'SEARCHING',
  SELECTING = 'SELECTING',
  GENERATING_CONTENT = 'GENERATING_CONTENT',
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR'
}

export interface PublishingConfig {
  telegramBotToken: string;
  telegramChatId: string;
  vkAccessToken: string;
  vkOwnerId: string; // Group ID usually starts with -
  wpUrl: string; // e.g., https://mysite.com
  wpUsername: string;
  wpAppPassword: string; // Generated via Application Passwords plugin
}

import { GoogleGenAI } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

// Initialize using process.env.API_KEY as per coding guidelines
// Note: In Vite, this is replaced at build time via define in vite.config.ts
const apiKey = process.env.API_KEY;
const ai = new GoogleGenAI({ apiKey: apiKey || '' });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' });
};

// Helper: Delay to prevent rate limiting (critical for image generation on free tier)
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

// Helper: Robust JSON Parser
const cleanAndParseJSON = (text: string): any => {
    // 1. Basic cleanup (Handles ```json, ```JSON, and just ```)
    let clean = text.replace(/```json/gi, '').replace(/```/g, '').trim();

    try {
        return JSON.parse(clean);
    } catch (e) {
        // 2. Advanced extraction for Objects {} and Arrays []
        // Find the first { or [
        const firstOpenBrace = clean.indexOf('{');
        const firstOpenBracket = clean.indexOf('[');

        let start = -1;
        // If both exist, pick the earlier one. If only one exists, pick it.
        if (firstOpenBrace !== -1 && firstOpenBracket !== -1) {
            start = Math.min(firstOpenBrace, firstOpenBracket);
        } else if (firstOpenBrace !== -1) {
            start = firstOpenBrace;
        } else if (firstOpenBracket !== -1) {
            start = firstOpenBracket;
        }

        if (start !== -1) {
            // Find the last corresponding closer
            const isObject = clean[start] === '{';
            const end = isObject ? clean.lastIndexOf('}') : clean.lastIndexOf(']');

            if (end !== -1 && end > start) {
                try {
                    const substring = clean.substring(start, end + 1);
                    return JSON.parse(substring);
                } catch (innerE) {
                     console.warn("Advanced JSON extraction failed:", innerE);
                }
            }
        }

        console.error("Failed to parse JSON. Raw text:", text);
        // Provide a clearer error
        throw new Error("AI вернул некорректные данные (JSON Parse Error). Попробуйте еще раз.");
    }
};

// 1. Search and Create Digest
export const generateDailyDigest = async (): Promise<DigestData> => {
  if (!apiKey) {
    throw new Error("API Key не найден. Проверьте настройки Variables на Railway (VITE_API_KEY).");
  }

  // Используем gemini-2.5-flash для скорости и стабильности
  const model = "gemini-2.5-flash"; 
  const dateStr = getCurrentDate();

  const systemInstruction = `
    Ты — ведущий аналитик издания "Первый Туристический". 
    Твой стиль — "интеллектуальная ирония" (референсы: Михаил Жванецкий, Иоанна Хмелевская, Аркадий Арканов).
    Ты видишь индустрию объемно: не только проблемы, но и возможности, но описываешь это с тонким юмором.

    Твоя задача: Собрать ГЛАВНЫЕ новости туризма СТРОГО за последние 24 часа для россиян.

    ПРАВИЛА ОТБОРА:
    1. ВРЕМЯ: Новости должны быть опубликованы НЕ РАНЕЕ, чем 24 часа назад.
    2. КОЛИЧЕСТВО: СТРОГО 10 (десять) новостей.
    3. БАЛАНС: Сочетай финансовые новости и вдохновляющие события.

    ВАЖНО ПО ОФОРМЛЕНИЮ (FORMATTING RULES):
    1. НИКАКИХ "***" (звездочек-разделителей).
    2. НИКАКОГО Markdown Bold (жирного шрифта **) в тексте новостей. Только чистый текст.
    3. Формат новости в списке:
       [Эмодзи, отражающее суть] [Заголовок]
       [Суть новости в 1-2 предложениях. Четко и ясно.]

    ФОРМАТ ОТВЕТА (RAW JSON ONLY):
    {
      "news": [
        { 
          "title": "Заголовок", 
          "summary": "Суть новости.", 
          "location": "Страна/Город", 
          "sourceUrl": "Источник", 
          "date": "Время/Дата" 
        }
      ],
      "hacks": ["Совет 1", "Совет 2"],
      "facts": ["Факт дня"],
      "formattedDigestText": "Текст поста для Telegram (ДЛИННЫЙ).\nСтиль: Умная беседа.\n\n🌍 ТУРИСТИЧЕСКИЙ ВЕСТНИК (${dateStr})\n\n[Здесь список из 10 новостей по формату: Эмодзи Заголовок + новая строка + описание]\n\n🥂 Мысль дня:\n[Ироничный короткий вывод]",
      "formattedShortDigest": "Короткий текст для бегущей строки.\nФормат: Эмодзи Заголовок новости • Эмодзи Заголовок новости • Эмодзи Заголовок новости...",
      "collagePrompt": "Photorealistic travel collage, 8k resolution, cinematic lighting, suitcases, passport, airplane window view, tropical beach, text 'TOURISM NEWS' overlay --ar 16:9"
    }
  `;

  const prompt = `
    Найди 10 самых важных и обсуждаемых новостей туризма за последние 24 часа.
    Используй Google Search для проверки фактов.
    ВЕРНИ ТОЛЬКО ВАЛИДНЫЙ JSON.
  `;

  let lastError;
  // Retry loop for robustness
  for (let attempt = 0; attempt < 2; attempt++) {
      try {
        const response = await ai.models.generateContent({
          model,
          contents: prompt,
          config: {
            tools: [{ googleSearch: {} }],
            systemInstruction: systemInstruction,
          },
        });

        const text = response.text || "";
        const parsed: DigestData = cleanAndParseJSON(text);

        if (parsed.news && parsed.news.length > 10) {
            parsed.news = parsed.news.slice(0, 10);
        }

        parsed.news = parsed.news.map((item: any, index: number) => ({
          ...item,
          id: `news-${index}-${Date.now()}`
        }));

        if (!parsed.collagePrompt) {
            parsed.collagePrompt = "Photorealistic travel collage, 8k resolution, cinematic lighting, suitcases, passport, airplane window view, tropical beach, text 'TOURISM NEWS' overlay --ar 16:9";
        }

        if (!parsed.formattedShortDigest) {
            parsed.formattedShortDigest = parsed.news.map(n => `⚡ ${n.title}`).join(' • ');
        }

        return parsed;

      } catch (error: any) {
        console.warn(`Digest generation attempt ${attempt + 1} failed:`, error);
        lastError = error;
        // Wait 2 seconds before retry
        await delay(2000);
      }
  }

  // If all attempts fail
  let msg = lastError?.message || "Unknown error";
  if (msg.includes('403') || msg.includes('location')) {
      msg = "⛔ ВАШ РЕГИОН ЗАБЛОКИРОВАН GOOGLE. Включите VPN.";
  } else if (msg.includes('API key')) {
      msg = "🔑 ОШИБКА КЛЮЧА: Проверьте настройки Railway -> Variables.";
  }
  throw new Error(msg);
};

// 1.5 Replace Specific News Items
export const replaceNewsItems = async (currentNews: NewsItem[], excludeIds: string[]): Promise<NewsItem[]> => {
    if (!apiKey) throw new Error("API Key missing");
    const model = "gemini-2.5-flash";

    const keptTitles = currentNews
        .filter(n => !excludeIds.includes(n.id))
        .map(n => n.title);

    const countToReplace = excludeIds.length;

    const prompt = `
      Нам нужно заменить ${countToReplace} новостей.
      Исключи эти темы: ${keptTitles.join(', ')}.
      Найди ${countToReplace} новых, актуальных новостей.
      Стиль: Интересный, важный инфоповод.
      ВЕРНИ ТОЛЬКО JSON массив NewsItem.
    `;

    try {
        const response = await ai.models.generateContent({
            model,
            contents: prompt,
            config: { tools: [{ googleSearch: {} }] }
        });
        const text = response.text || "[]";
        const newItems: any[] = cleanAndParseJSON(text);
        return newItems.map((item: any, index: number) => ({
            ...item,
            id: `news-replaced-${index}-${Date.now()}`
        }));
    } catch (e: any) {
        throw new Error("Не удалось найти замену: " + e.message);
    }
};

export const generateCreativeContent = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  if (!apiKey) throw new Error("API Key missing");

  const models = ["gemini-3-pro-preview", "gemini-2.5-flash"];
  let lastError;

  const prompt = `
    ТЫ — ВЕДУЩИЙ КОЛУМНИСТ ИЗДАНИЯ "ПЕРВЫЙ ТУРИСТИЧЕСКИЙ".
    Стилистика: смесь Иоанны Хмелевской, Аркадия Арканова и Михаила Жванецкого.

    ГЛАВНОЕ ПРАВИЛО ПОВЕСТВОВАНИЯ:
    1. КАТЕГОРИЧЕСКИЙ ЗАПРЕТ НА ПЕРВОЕ ЛИЦО. Не используй слова: "Я", "Мной", "Мы", "Наш", "Скажу вам".
    2. ИСПОЛЬЗУЙ БЕЗЛИЧНЫЕ ИЛИ БРЕНДИРОВАННЫЕ ОБОРОТЫ:
       - "Как стало известно Первому Туристическому..."
       - "По данным, которыми располагает Первый Туристический..."
       - "Эксперты Первого Туристического отмечают..."
       - "В кулуарах шепчутся, что..."
       - "Оказывается..."

    ТОН И СТИЛЬ:
    1. ИНТЕЛЛЕКТУАЛЬНАЯ ИРОНИЯ: Тонкий юмор, парадоксальные выводы.
    2. ДОСТОВЕРНОСТЬ: Факты должны быть 100% реальными. Никаких выдумок, только реальная подача.
    3. ОФОРМЛЕНИЕ: Никаких звездочек "***". Никаких лишних символов.

    РАБОТА С ФАКТУРОЙ:
    1. Найди через Google Search цифры и детали этой новости.
    2. ЦИТАТА: Найди реальные слова эксперта, но подай их через призму иронии (но саму цитату не искажай).

    ВХОДНЫЕ ДАННЫЕ:
    Новость: "${newsItem.title}" (${newsItem.summary})

    ЗАДАЧА:
    1. Статья для сайта (3000+ знаков). 
       Структура: Заголовок (Парадоксальный) -> Лид (В стиле "Первого Туристического") -> Тело с фактами и иронией -> Цитата -> Вывод.

    2. Пост для Telegram (Суть + Цифра + Легкий юмор + хештеги с #).
    3. Пост для VK (С вопросом к аудитории + хештеги с #).

    ФОРМАТ ХЕШТЕГОВ (СТРОГО):
    - Для сайта (поле hashtags): Слова через запятую БЕЗ значка # (Пример: туризм, авиа, отпуск)
    - Для соцсетей (внутри content): Слова С решеткой # (Пример: #туризм #отпуск)

    СТРУКТУРА ОТВЕТА (JSON):
    {
      "siteArticle": { "headline": "...", "content": "Markdown...", "hashtags": "тег1, тег2, тег3" },
      "telegramPost": { "content": "Текст...\n\n#тег1 #тег2" },
      "vkPost": { "content": "Текст...\n\n#тег1 #тег2" },
      "imagePrompts": ["English prompt for National Geographic style photo...", "English prompt..."],
      "metaDescription": "..."
    }
  `;

  for (const model of models) {
    try {
        const response = await ai.models.generateContent({
          model,
          contents: prompt,
          config: { tools: [{ googleSearch: {} }] }
        });

        const text = response.text || "{}";
        const json = cleanAndParseJSON(text);

        if (!json.siteArticle?.content) throw new Error("Content missing");

        const enforcedPrompts = (json.imagePrompts || []).map((p: string) => {
            // Remove aspect ratio flags if present to re-add them cleanly
            let clean = p.replace(/--ar\s+\d+:\d+/g, '').trim();
            // Prefix to ensure hyper-realism
            return `Award winning National Geographic photography, shot on Sony A7R IV, 8k uhd, dslr, soft lighting, high quality, film grain, Fujifilm XT3, ${clean} --ar 16:9`;
        });

        return {
          newsId: newsItem.id,
          ...json,
          imagePrompts: enforcedPrompts,
          generatedImages: []
        };

    } catch (error: any) {
        console.warn(`Content generation failed with model ${model}:`, error);
        lastError = error;
    }
  }
  throw new Error(`Ошибка генерации контента: ${lastError?.message}`);
};

export const generateImage = async (prompt: string, aspectRatio: string = "16:9"): Promise<string | null> => {
    if (!apiKey) return null;

    // Clean existing AR flags
    const cleanPrompt = prompt.replace(/--ar\s+\d+:\d+/g, '').trim();

    // Safety Force English & Hyper-realism settings:
    const finalPrompt = `hyperrealistic, raw photo, 8k uhd, dslr, soft lighting, high quality, film grain, Fujifilm XT3, ${cleanPrompt} --no cgi, 3d, cartoon, drawing, anime, text, watermark, illustration, painting`;

    // 1. Try Pro Model (Best quality)
    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-pro-image-preview",
            contents: { parts: [{ text: finalPrompt }] },
            config: { imageConfig: { aspectRatio, imageSize: "1K" } }
        });
        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (part?.inlineData?.data) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    } catch (e) {
        console.warn("Pro Image failed, trying Flash with Retry...", e);
    }

    // Delay before fallback to recover from potential rate limits
    await delay(1000);

    // 2. Try Flash Model with Retry logic
    // We try twice to ensure high success rate on unstable connections/limits
    for (let attempt = 0; attempt < 2; attempt++) {
        try {
            const response = await ai.models.generateContent({
                model: "gemini-2.5-flash-image",
                contents: { parts: [{ text: finalPrompt }] },
                config: { imageConfig: { aspectRatio } }
            });
            const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
            if (part?.inlineData?.data) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        } catch (e: any) {
            console.warn(`Flash Image Attempt ${attempt + 1} failed:`, e);
            // Exponential backoff: wait 2s, then 4s
            await delay((attempt + 1) * 2000);
        }
    }

    console.error("All image generation attempts failed for prompt:", finalPrompt);
    return null;
}

export const generateImagesForPack = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  const promptsToRun = prompts.slice(0, 3); 

  for (const p of promptsToRun) {
      // Increased delay to 5 seconds to strictly avoid Rate Limiting on Railway/Cloud
      await delay(5000); 

      const img = await generateImage(p);
      if (img) images.push(img);
      else images.push(`https://placehold.co/1024x576/e2e8f0/475569?text=Image+Generation+Error`);
  }
  return images;
};

import React, { useState } from 'react';
import { GeneratedContentPack, PublishingConfig } from '../types';
import { publishToTelegram, publishToVK, publishToWordPress } from '../services/publishingService';
import ReactMarkdown from 'react-markdown';

interface ResultViewerProps {
  pack: GeneratedContentPack;
  pubConfig: PublishingConfig;
}

export const ResultViewer: React.FC<ResultViewerProps> = ({ pack, pubConfig }) => {
  const [activeTab, setActiveTab] = useState<'site' | 'telegram' | 'vk' | 'prompts'>('site');
  const [copied, setCopied] = useState(false);
  const [publishing, setPublishing] = useState<string | null>(null); // 'telegram', 'vk', 'wp'
  const [pubStatus, setPubStatus] = useState<{ [key: string]: { success: boolean; msg: string } }>({});

  // Date scheduling
  const [scheduleDate, setScheduleDate] = useState<string>('');

  const tabLabels = {
    site: 'Статья на сайт',
    telegram: 'Telegram',
    vk: 'ВКонтакте',
    prompts: 'Тех. данные'
  };

  const copyContent = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handlePublish = async (platform: 'telegram' | 'vk' | 'wp') => {
    setPublishing(platform);
    setPubStatus(prev => ({ ...prev, [platform]: { success: false, msg: '' } }));

    const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;
    const isScheduled = !!dateObj;

    try {
      if (platform === 'telegram') {
        // Telegram supports scheduling via 'schedule_date' parameter
        await publishToTelegram(pubConfig, pack.telegramPost.content, pack.generatedImages[0], dateObj);
        setPubStatus(prev => ({ ...prev, telegram: { success: true, msg: isScheduled ? 'В очереди!' : 'Отправлено!' } }));
      }
      else if (platform === 'vk') {
        // Now attempts image upload too + scheduling
        await publishToVK(pubConfig, pack.vkPost.content, pack.generatedImages[0], dateObj);
        setPubStatus(prev => ({ ...prev, vk: { success: true, msg: isScheduled ? 'В очереди!' : 'Опубликовано!' } }));
      }
      else if (platform === 'wp') {
        // Send article + first image as feature + scheduling
        await publishToWordPress(
            pubConfig, 
            pack.siteArticle.headline, 
            pack.siteArticle.content, 
            pack.generatedImages[0], 
            pack.siteArticle.hashtags,
            dateObj
        );
        setPubStatus(prev => ({ ...prev, wp: { success: true, msg: isScheduled ? 'Запланировано!' : 'Черновик создан!' } }));
      }
    } catch (e: any) {
      setPubStatus(prev => ({ ...prev, [platform]: { success: false, msg: `Ошибка: ${e.message}` } }));
    } finally {
      setPublishing(null);
    }
  };

  if (pack.error) {
    return (
      <div className="bg-red-50 p-6 rounded-2xl border border-red-200 h-full flex flex-col items-center justify-center text-center">
        <h3 className="text-lg font-bold text-red-700">Ошибка генерации</h3>
        <p className="text-red-600 mt-2 text-sm">{pack.error}</p>
        <p className="text-slate-500 text-xs mt-4">Попробуйте обновить страницу или сгенерировать снова.</p>
      </div>
    );
  }

  // Safety check: If for some reason siteArticle is missing but error wasn't set.
  if (!pack.siteArticle || !pack.siteArticle.content) {
    return (
      <div className="bg-amber-50 p-6 rounded-2xl border border-amber-200 h-full flex flex-col items-center justify-center text-center">
        <h3 className="text-lg font-bold text-amber-700">Данные неполные</h3>
        <p className="text-amber-600 mt-2 text-sm">AI вернул пустой ответ для этой статьи.</p>
      </div>
    );
  }

  // Publishing Controls Helper
  const PublishControls = ({ platform, label }: { platform: 'wp' | 'vk' | 'telegram', label: string }) => {
     const isScheduled = !!scheduleDate;

     return (
         <div className="mb-4 bg-slate-50 p-3 rounded-lg border border-slate-200">
             <div className="flex items-center justify-between flex-wrap gap-3">
                 <div className="flex items-center gap-2">
                     <span className={`text-xs font-bold ${platform === 'telegram' ? 'text-blue-500' : platform === 'vk' ? 'text-blue-700' : 'text-slate-700'}`}>{label}</span>
                     {pubStatus[platform]?.msg && <span className={`text-[10px] ${pubStatus[platform].success ? 'text-green-600' : 'text-red-600'}`}>{pubStatus[platform].msg}</span>}
                 </div>

                 <div className="flex items-center gap-2">
                    <input 
                        type="datetime-local" 
                        value={scheduleDate}
                        onChange={(e) => setScheduleDate(e.target.value)}
                        className="text-xs border border-slate-300 rounded px-2 py-1.5 bg-white text-slate-600 focus:ring-2 focus:ring-indigo-500 outline-none w-36"
                        title="Выберите дату для отложенной публикации"
                    />

                    <button 
                        onClick={() => handlePublish(platform)}
                        disabled={!!publishing}
                        className={`text-white text-xs px-4 py-1.5 rounded font-bold disabled:opacity-50 transition-colors ${
                            isScheduled
                            ? 'bg-purple-600 hover:bg-purple-700' 
                            : 'bg-indigo-600 hover:bg-indigo-700'
                        }`}
                    >
                        {publishing === platform ? '...' : (isScheduled ? 'Отложить' : 'Опубликовать')}
                    </button>
                 </div>
             </div>
         </div>
     );
  };

  return (
    <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-200 flex flex-col h-full">
      {/* Header / Tabs */}
      <div className="bg-slate-50 border-b border-slate-200 p-2 flex justify-between items-center">
        <div className="flex space-x-1 overflow-x-auto">
          {(['site', 'telegram', 'vk', 'prompts'] as const).map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`px-3 py-1.5 text-xs font-bold rounded-md uppercase tracking-wider transition-colors whitespace-nowrap ${
                activeTab === tab 
                  ? 'bg-white text-indigo-600 shadow-sm border border-slate-200' 
                  : 'text-slate-500 hover:bg-slate-100'
              }`}
            >
              {tabLabels[tab]}
            </button>
          ))}
        </div>
        <button 
           onClick={() => {
             if (activeTab === 'site') copyContent(pack.siteArticle.content);
             if (activeTab === 'telegram') copyContent(pack.telegramPost.content);
             if (activeTab === 'vk') copyContent(pack.vkPost.content);
           }} 
