    3. Пост для VK (С вопросом к аудитории + хештеги с #).

    ФОРМАТ ХЕШТЕГОВ (СТРОГО):
    - Для сайта (поле hashtags): Слова через запятую БЕЗ значка # (Пример: туризм, авиа, отпуск)
    - Для соцсетей (внутри content): Слова С решеткой # (Пример: #туризм #отпуск)

    ИЛЛЮСТРАЦИИ:
    Создай 3 разных промпта для фотореалистичных изображений, описывающих разные аспекты новости.

    СТРУКТУРА ОТВЕТА (JSON):
    {
      "siteArticle": { "headline": "...", "content": "Markdown...", "hashtags": "тег1, тег2, тег3" },
      "telegramPost": { "content": "Текст...\n\n#тег1 #тег2" },
      "vkPost": { "content": "Текст...\n\n#тег1 #тег2" },
      "imagePrompts": ["Prompt 1...", "Prompt 2...", "Prompt 3..."],
      "metaDescription": "..."
    }
  `;

  for (const model of models) {
    try {
        const response = await ai.models.generateContent({
          model,
          contents: prompt,
          config: { tools: [{ googleSearch: {} }] }
        });

        const text = response.text || "{}";
        const json = cleanAndParseJSON(text);

        if (!json.siteArticle?.content) throw new Error("Content missing");

        const enforcedPrompts = (json.imagePrompts || []).map((p: string) => {
            // Remove aspect ratio flags if present to re-add them cleanly
            let clean = p.replace(/--ar\s+\d+:\d+/g, '').trim();
            // Prefix to ensure hyper-realism. STRONGER PROMPT ENGINEERING.
            return `Hyper-realistic raw photography, shot on Sony A7R IV, 85mm lens, f/1.8, cinematic lighting, 8k uhd, highly detailed, photorealistic texture, ${clean} --ar 16:9 --no illustration, cartoon, anime, 3d render, drawing, painting, cgi, sketch`;
        });

        return {
          newsId: newsItem.id,
          ...json,
          imagePrompts: enforcedPrompts,
          generatedImages: []
        };

    } catch (error: any) {
        console.warn(`Content generation failed with model ${model}:`, error);
        lastError = error;
    }
  }
  throw new Error(`Ошибка генерации контента: ${lastError?.message}`);
};

export const generateImage = async (prompt: string, aspectRatio: string = "16:9"): Promise<string | null> => {
    if (!apiKey) return null;

    // Clean existing AR flags
    const cleanPrompt = prompt.replace(/--ar\s+\d+:\d+/g, '').trim();

    // Safety Force English & Hyper-realism settings:
    // Even stronger negative prompts to avoid "artistic" interpretations
    const finalPrompt = `raw photo, hyperrealistic, 8k uhd, dslr, soft cinematic lighting, film grain, Fujifilm XT3, ${cleanPrompt} --no cgi, 3d, cartoon, drawing, anime, text, watermark, illustration, painting, vector art, graphic design`;

    // 1. Try Pro Model (Best quality)
    try {
        const response = await ai.models.generateContent({
            model: "gemini-3-pro-image-preview",
            contents: { parts: [{ text: finalPrompt }] },
            config: { imageConfig: { aspectRatio, imageSize: "1K" } }
        });
        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
        if (part?.inlineData?.data) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    } catch (e) {
        console.warn("Pro Image failed, trying Flash with Retry...", e);
    }

    // Delay before fallback to recover from potential rate limits
    await delay(1000);

    // 2. Try Flash Model with Retry logic
    // We try twice to ensure high success rate on unstable connections/limits
    for (let attempt = 0; attempt < 2; attempt++) {
        try {
            const response = await ai.models.generateContent({
                model: "gemini-2.5-flash-image",
                contents: { parts: [{ text: finalPrompt }] },
                config: { imageConfig: { aspectRatio } }
            });
            const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
            if (part?.inlineData?.data) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        } catch (e: any) {
            console.warn(`Flash Image Attempt ${attempt + 1} failed:`, e);
            // Exponential backoff: wait 2s, then 4s
            await delay((attempt + 1) * 2000);
        }
    }

    console.error("All image generation attempts failed for prompt:", finalPrompt);
    return null;
}

export const generateImagesForPack = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  // Ensure we try to generate up to 3 images
  const promptsToRun = prompts.slice(0, 3); 

  for (const p of promptsToRun) {
      // Increased delay to 5 seconds to strictly avoid Rate Limiting on Railway/Cloud
      await delay(5000); 

      const img = await generateImage(p);
      if (img) images.push(img);
      else images.push(`https://placehold.co/1024x576/e2e8f0/475569?text=Image+Generation+Error`);
  }
  return images;
};

import React, { useState, useCallback, useEffect } from 'react';
import { generateDailyDigest, generateCreativeContent, generateImagesForPack, generateImage, replaceNewsItems } from './services/geminiService';
import { AppState, DigestData, GeneratedContentPack, PublishingConfig } from './types';
import { NewsCard } from './components/NewsCard';
import { ResultViewer } from './components/ResultViewer';
import { DigestPostViewer } from './components/DigestPostViewer';
import { SettingsModal } from './components/SettingsModal';
import { MAX_SELECTION } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [digest, setDigest] = useState<DigestData | null>(null);
  const [selectedNewsIds, setSelectedNewsIds] = useState<string[]>([]);
  const [markedForReplaceIds, setMarkedForReplaceIds] = useState<string[]>([]); // New state for replacement
  const [generatedResults, setGeneratedResults] = useState<GeneratedContentPack[]>([]);
  const [errorMsg, setErrorMsg] = useState<string>('');
  const [statusMessage, setStatusMessage] = useState<string>('');

  // Settings State
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [pubConfig, setPubConfig] = useState<PublishingConfig>({
    telegramBotToken: '',
    telegramChatId: '',
    vkAccessToken: '',
    vkOwnerId: '',
    wpUrl: '',
    wpUsername: '',
    wpAppPassword: ''
  });

  // Load settings from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem('tourgenius_config');
    if (saved) {
      try {
        setPubConfig(JSON.parse(saved));
      } catch (e) { console.error(e); }
    }
  }, []);

  const handleSaveConfig = (newConfig: PublishingConfig) => {
    setPubConfig(newConfig);
    localStorage.setItem('tourgenius_config', JSON.stringify(newConfig));
  };

  const handleStartResearch = useCallback(async () => {
    setAppState(AppState.SEARCHING);
    setStatusMessage("Сканирую новости туризма за последние 24 часа...");
    try {
      const data = await generateDailyDigest();

      setDigest(data);
      setAppState(AppState.SELECTING);

      if (data.collagePrompt) {
          generateImage(data.collagePrompt).then(img => {
             if (img) {
                 setDigest(prev => prev ? ({ ...prev, collageImage: img }) : null);
             } else {
                 setDigest(prev => prev ? ({ ...prev, collageImage: 'https://placehold.co/1024x576/e2e8f0/64748b?text=Collage+Generation+Failed' }) : null);
             }
          });
      }

    } catch (e: any) {
      setErrorMsg(e.message || "Неизвестная ошибка во время поиска.");
      setAppState(AppState.ERROR);
    }
  }, []);

  const toggleNewsSelection = (id: string) => {
    setSelectedNewsIds(prev => {
      if (prev.includes(id)) {
        return prev.filter(i => i !== id);
      }
      if (prev.length >= MAX_SELECTION) {
        return prev;
      }
      return [...prev, id];
    });
  };

  const toggleMarkForReplace = (id: string) => {
      // If we mark it for replacement, we should unselect it for generation
      if (selectedNewsIds.includes(id)) {
          toggleNewsSelection(id);
      }

      setMarkedForReplaceIds(prev => {
          if (prev.includes(id)) return prev.filter(i => i !== id);
          return [...prev, id];
      });
  };

  const handleExecuteReplacement = async () => {
      if (!digest || markedForReplaceIds.length === 0) return;

      const oldCount = markedForReplaceIds.length;
      setStatusMessage(`Ищу замену для ${oldCount} новостей...`);
      setAppState(AppState.SEARCHING); // Reuse searching UI

      try {
          const newItems = await replaceNewsItems(digest.news, markedForReplaceIds);

          setDigest(prev => {
              if (!prev) return null;
              // Filter out old items
              const keptItems = prev.news.filter(n => !markedForReplaceIds.includes(n.id));
              // Combine kept items with new items
              return {
                  ...prev,
                  news: [...keptItems, ...newItems]
              };
          });

          setMarkedForReplaceIds([]); // Clear queue
          setAppState(AppState.SELECTING); // Go back to selection
      } catch (e: any) {
          setErrorMsg("Не удалось заменить новости: " + e.message);
          setAppState(AppState.ERROR);
      }
  };

  const handleGenerateContent = async () => {
    if (selectedNewsIds.length === 0) return;

    setAppState(AppState.GENERATING_CONTENT);
    setErrorMsg('');
    setGeneratedResults([]); // Clear previous results

    try {
      const selectedItems = digest?.news.filter(n => selectedNewsIds.includes(n.id)) || [];

      // We loop through sequentially but update state incrementally.
      // If one fails, we catch the error inside the loop so the others can still proceed.
      for (let i = 0; i < selectedItems.length; i++) {
        const item = selectedItems[i];

        // Add small delay between articles to avoid rate limits
        if (i > 0) {
            setStatusMessage(`Ожидание API перед следующей статьей...`);
            await new Promise(resolve => setTimeout(resolve, 2000));
        }

        try {
            setStatusMessage(`Пишу статью ${i+1}/${selectedItems.length}: "${item.title.substring(0, 20)}..."`);

            const content = await generateCreativeContent(item);

            setStatusMessage(`Рисую иллюстрации ${i+1}/${selectedItems.length}: "${item.title.substring(0, 20)}..."`);
            const images = await generateImagesForPack(content.imagePrompts);

            const newPack: GeneratedContentPack = {
              ...content,
              generatedImages: images
            };

            // Add result immediately so user sees progress
            setGeneratedResults(prev => [...prev, newPack]);

        } catch (itemError: any) {
            console.error(`Error generating for item ${item.id}:`, itemError);
            // Push an error pack so the column shows up as failed but exists
            setGeneratedResults(prev => [...prev, {
                newsId: item.id,
                siteArticle: { headline: 'Ошибка генерации', content: 'Не удалось создать контент для этой новости.', hashtags: '' },
                telegramPost: { content: '' },
                vkPost: { content: '' },
                imagePrompts: [],
                metaDescription: '',
                generatedImages: [],
                error: itemError.message || "Unknown error"
            }]);
        }
      }

    } catch (e: any) {
      setErrorMsg(e.message || "Critical error during generation loop.");
      setAppState(AppState.ERROR);
    } finally {
        setAppState(AppState.COMPLETED);
    }
  };

  return (
    <div className="min-h-screen bg-[#f5f5f7] text-brand-dark pb-10 font-sans">
      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        config={pubConfig}
        onSave={handleSaveConfig}
      />

      {/* Navbar Brand Dark */}
      <nav className="bg-brand-dark border-b border-brand-dark sticky top-0 z-50 shadow-md">
        <div className="max-w-[1920px] mx-auto px-4">
          <div className="flex justify-between h-16 items-center">
            <div className="flex items-center cursor-pointer group" onClick={() => setAppState(AppState.IDLE)}>
              <div className="bg-brand-orange w-8 h-8 rounded-lg flex items-center justify-center mr-3 shadow-lg group-hover:rotate-3 transition-transform">
                 <span className="text-white text-lg">🌴</span>
              </div>
              <h1 className="text-xl font-bold text-white tracking-wide">
                ПЕРВЫЙ <span className="text-brand-orange">ТУРИСТИЧЕСКИЙ</span>
              </h1>
            </div>
            <div className="flex items-center gap-4">
              <div className="text-xs font-mono text-brand-grey hidden md:block border border-brand-grey/30 px-2 py-1 rounded">
                v3.5 (Brand Edition)
              </div>
              <button 
                onClick={() => setIsSettingsOpen(true)}
                className="text-white hover:text-brand-orange transition-colors p-2"
                title="Настройки публикации"
              >
                ⚙️
              </button>
            </div>
          </div>
        </div>
      </nav>

      <main className="max-w-[1920px] mx-auto px-4 py-8">

        {/* Error Display */}
        {appState === AppState.ERROR && (
          <div className="bg-red-50 border-l-4 border-red-500 p-4 mb-6 rounded-r shadow-sm">
            <div className="flex">
              <div className="ml-3">
                <p className="text-sm text-red-700 font-bold">Произошла ошибка</p>
                <p className="text-sm text-red-600">{errorMsg}</p>
                <button 
                  onClick={() => setAppState(AppState.IDLE)}
                  className="mt-2 text-xs font-semibold text-red-800 underline"
                >
                  Сбросить приложение
                </button>
              </div>
            </div>
          </div>
        )}

        {/* State: IDLE */}
        {appState === AppState.IDLE && (
          <div className="flex flex-col items-center justify-center py-20 text-center">
            <div className="bg-white p-12 rounded-3xl shadow-2xl max-w-2xl w-full border border-slate-100 relative overflow-hidden">
              <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-brand-orange to-red-500"></div>

              <div className="w-24 h-24 bg-brand-orange/10 rounded-full flex items-center justify-center text-5xl mb-6 mx-auto animate-pulse-slow text-brand-orange">
                ✈️
              </div>
              <h2 className="text-4xl font-black text-brand-dark mb-4 font-sans uppercase tracking-tight">
                Ежедневная Сводка
              </h2>
              <p className="text-brand-grey mb-8 text-lg leading-relaxed font-light">
                Интеллектуальный анализ <span className="font-bold text-brand-orange">10 главных новостей</span> за 24 часа. 
                Дайджест, коллажи и <span className="font-bold text-brand-dark">{MAX_SELECTION} эксклюзивные статьи</span> в стиле "Первого Туристического".
              </p>
              <button
                onClick={handleStartResearch}
                className="inline-flex items-center px-12 py-5 text-lg font-bold uppercase tracking-wider rounded-lg shadow-xl text-white bg-brand-orange hover:bg-orange-600 hover:shadow-2xl transition-all transform hover:-translate-y-1 active:translate-y-0 brand-glow"
              >
                Запустить Эфир
              </button>
            </div>
          </div>
        )}

        {/* State: LOADING */}
        {(appState === AppState.SEARCHING || appState === AppState.GENERATING_CONTENT) && (
          <div className="flex flex-col items-center justify-center py-40">
            <div className="relative w-24 h-24 mb-8">
               <div className="absolute top-0 left-0 w-full h-full border-4 border-slate-200 rounded-full"></div>
               <div className="absolute top-0 left-0 w-full h-full border-4 border-brand-orange rounded-full animate-spin border-t-transparent"></div>
            </div>
            <h3 className="text-3xl font-bold text-brand-dark animate-pulse">{statusMessage}</h3>
            <p className="text-brand-grey mt-3 text-sm font-bold uppercase tracking-[0.2em]">Обработка данных</p>

            {/* Show incremental results during generation */}
            {generatedResults.length > 0 && (
                 <div className="mt-8 flex gap-2">
                     {generatedResults.map((res, idx) => (
                         <div key={idx} className={`w-3 h-3 rounded-full ${res.error ? 'bg-red-400' : 'bg-brand-orange'}`}></div>
                     ))}
                 </div>
            )}
          </div>
        )}

        {/* State: SELECTING */}
        {appState === AppState.SELECTING && digest && (
          <div className="animate-fade-in pb-20">
            <header className="flex flex-col md:flex-row justify-between items-end border-b border-slate-200 pb-6 mb-8 sticky top-16 bg-[#f5f5f7]/95 backdrop-blur z-40 py-4">
              <div>
                <h2 className="text-3xl font-black text-brand-dark font-sans uppercase">Редакция Выпуска</h2>
                <p className="text-brand-grey mt-2">
                    Выберите <span className="font-bold text-brand-orange">{MAX_SELECTION} темы</span> для детальной проработки.
                </p>
              </div>
              <div className="flex gap-4 mt-4 md:mt-0">
                  {markedForReplaceIds.length > 0 && (
                      <button
                        onClick={handleExecuteReplacement}
                        className="px-6 py-3 rounded-lg font-bold shadow-md transition-all bg-red-50 text-red-600 hover:bg-red-100 border border-red-200 flex items-center gap-2"
                      >
                         <svg xmlns="http://www.w3.org/2000/svg" className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                             <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
                         </svg>
                         Заменить ({markedForReplaceIds.length})
                      </button>
                  )}

                  <button
                    onClick={handleGenerateContent}
                    disabled={selectedNewsIds.length !== MAX_SELECTION || markedForReplaceIds.length > 0}
                    className={`px-8 py-3 rounded-lg font-bold shadow-lg transition-all uppercase tracking-wide ${
                      selectedNewsIds.length === MAX_SELECTION && markedForReplaceIds.length === 0
                        ? 'bg-brand-orange text-white hover:bg-orange-600 hover:scale-105 brand-glow'
                        : 'bg-slate-200 text-slate-400 cursor-not-allowed'
                    }`}
                  >
                    Генерировать ({selectedNewsIds.length}/{MAX_SELECTION})
                  </button>
              </div>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {digest.news.map((item) => (
                <NewsCard 
                  key={item.id} 
                  item={item} 
                  isSelected={selectedNewsIds.includes(item.id)} 
                  onToggle={toggleNewsSelection}
                  onMarkReplace={toggleMarkForReplace}
                  isMarkedForReplace={markedForReplaceIds.includes(item.id)}
                />
              ))}
            </div>

            {/* Quick preview of Hacks/Facts */}
            <div className="mt-12 grid grid-cols-1 md:grid-cols-2 gap-6 opacity-90">
               <div className="bg-white p-6 rounded-xl border border-orange-100 shadow-sm relative overflow-hidden">
                  <div className="absolute top-0 right-0 w-16 h-16 bg-orange-100 rounded-bl-full opacity-50"></div>
                  <h4 className="font-bold text-brand-orange text-sm uppercase mb-3 tracking-wider">Лайфхаки</h4>
                  <p className="text-sm text-brand-dark leading-relaxed">{digest.hacks.join(' • ')}</p>
               </div>
               <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
                  <h4 className="font-bold text-brand-grey text-sm uppercase mb-3 tracking-wider">Факты</h4>
                  <p className="text-sm text-brand-dark leading-relaxed">{digest.facts.join(' • ')}</p>
               </div>
            </div>
          </div>
        )}

        {/* State: COMPLETED */}
        {appState === AppState.COMPLETED && (
          <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 h-[85vh]">
             {/* Digest Column */}
             <div className="xl:col-span-1 h-full">
                {digest && <DigestPostViewer digest={digest} pubConfig={pubConfig} />}
             </div>

             {/* Articles Columns */}
             {generatedResults.map((pack) => (
                <div key={pack.newsId} className="xl:col-span-1 h-full">
                   <ResultViewer pack={pack} pubConfig={pubConfig} />
                </div>
             ))}

             {/* Fallback placeholders if less than MAX_SELECTION results were generated */}
             {Array.from({ length: Math.max(0, MAX_SELECTION - generatedResults.length) }).map((_, i) => (
                 <div key={i} className="xl:col-span-1 h-full bg-slate-100 rounded-2xl border-2 border-dashed border-slate-300 flex items-center justify-center text-slate-400 font-bold uppercase tracking-widest">
                     Ожидание...
                 </div>
             ))}
          </div>
        )}

      </main>
    </div>
  );
};

