  item: NewsItem;
  isSelected: boolean;
  onToggle: (id: string) => void;
  onMarkReplace: (id: string) => void; // New handler
  isMarkedForReplace: boolean; // New state prop
}

export const NewsCard: React.FC<NewsCardProps> = ({ item, isSelected, onToggle, onMarkReplace, isMarkedForReplace }) => {
  return (
    <div 
      className={`relative p-6 rounded-xl border transition-all duration-300 group ${
        isMarkedForReplace
          ? 'border-red-200 bg-red-50 opacity-60 grayscale'
          : isSelected 
            ? 'border-brand-orange bg-white shadow-xl shadow-orange-100 ring-2 ring-brand-orange cursor-pointer transform scale-[1.02] z-10' 
