        <div className="flex justify-between items-start mb-3">
          <span className={`inline-block px-2 py-1 text-[10px] font-bold uppercase tracking-wider rounded-md ${isMarkedForReplace ? 'bg-slate-200 text-slate-500' : 'text-white bg-brand-grey'}`}>
            {item.location || 'Мир'}
          </span>

          <div className="flex gap-2">
            {/* Selection Indicator */}
            <div className={`w-6 h-6 rounded-full border flex items-center justify-center transition-colors ${isSelected ? 'bg-brand-orange border-brand-orange' : 'border-slate-300 bg-white group-hover:border-brand-orange'}`}>
              {isSelected && (
                <svg className="w-4 h-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                </svg>
              )}
            </div>
          </div>
        </div>

        <h3 className={`text-lg font-bold mb-3 leading-snug font-sans ${isMarkedForReplace ? 'text-slate-400 line-through' : 'text-brand-dark group-hover:text-brand-orange transition-colors'}`}>
            {item.title}
        </h3>
        <p className={`text-sm leading-relaxed mb-4 flex-grow ${isMarkedForReplace ? 'text-slate-400' : 'text-brand-grey'}`}>
            {item.summary}
        </p>

        <div className="pt-3 border-t border-slate-100 flex flex-wrap gap-y-1 justify-between items-center text-[10px] text-slate-400 uppercase tracking-wide">
