                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            ) : (
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
            )}
        </svg>
      </button>
    </div>
  );
};

import React, { useState } from 'react';
import { GeneratedContentPack, PublishingConfig } from '../types';
import { publishToTelegram, publishToVK, publishToWordPress } from '../services/publishingService';
import ReactMarkdown from 'react-markdown';

interface ResultViewerProps {
  pack: GeneratedContentPack;
  pubConfig: PublishingConfig;
}

export const ResultViewer: React.FC<ResultViewerProps> = ({ pack, pubConfig }) => {
  const [activeTab, setActiveTab] = useState<'site' | 'telegram' | 'vk' | 'prompts'>('site');
  const [copied, setCopied] = useState(false);
  const [publishing, setPublishing] = useState<string | null>(null); // 'telegram', 'vk', 'wp'
  const [pubStatus, setPubStatus] = useState<{ [key: string]: { success: boolean; msg: string } }>({});

  // Date scheduling
  const [scheduleDate, setScheduleDate] = useState<string>('');

  const tabLabels = {
    site: 'Статья на сайт',
    telegram: 'Telegram',
    vk: 'ВКонтакте',
    prompts: 'Тех. данные'
  };

  const copyContent = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handlePublish = async (platform: 'telegram' | 'vk' | 'wp') => {
    setPublishing(platform);
    setPubStatus(prev => ({ ...prev, [platform]: { success: false, msg: '' } }));

    const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;
    const isScheduled = !!dateObj;

    try {
      if (platform === 'telegram') {
        // Telegram supports scheduling via 'schedule_date' parameter
        await publishToTelegram(pubConfig, pack.telegramPost.content, pack.generatedImages[0], dateObj);
        setPubStatus(prev => ({ ...prev, telegram: { success: true, msg: isScheduled ? 'В очереди!' : 'Отправлено!' } }));
      }
      else if (platform === 'vk') {
        // Now attempts image upload too + scheduling
        await publishToVK(pubConfig, pack.vkPost.content, pack.generatedImages[0], dateObj);
        setPubStatus(prev => ({ ...prev, vk: { success: true, msg: isScheduled ? 'В очереди!' : 'Опубликовано!' } }));
      }
      else if (platform === 'wp') {
        // Send article + first image as feature + scheduling
        await publishToWordPress(
            pubConfig, 
            pack.siteArticle.headline, 
            pack.siteArticle.content, 
            pack.generatedImages[0], 
            pack.siteArticle.hashtags,
            dateObj
        );
        setPubStatus(prev => ({ ...prev, wp: { success: true, msg: isScheduled ? 'Запланировано!' : 'Черновик создан!' } }));
      }
    } catch (e: any) {
      setPubStatus(prev => ({ ...prev, [platform]: { success: false, msg: `Ошибка: ${e.message}` } }));
    } finally {
      setPublishing(null);
    }
  };

  if (pack.error) {
    return (
      <div className="bg-red-50 p-6 rounded-2xl border border-red-200 h-full flex flex-col items-center justify-center text-center">
        <h3 className="text-lg font-bold text-red-700">Ошибка генерации</h3>
        <p className="text-red-600 mt-2 text-sm">{pack.error}</p>
        <p className="text-slate-500 text-xs mt-4">Попробуйте обновить страницу или сгенерировать снова.</p>
      </div>
    );
  }

  // Safety check: If for some reason siteArticle is missing but error wasn't set.
  if (!pack.siteArticle || !pack.siteArticle.content) {
    return (
      <div className="bg-amber-50 p-6 rounded-2xl border border-amber-200 h-full flex flex-col items-center justify-center text-center">
        <h3 className="text-lg font-bold text-amber-700">Данные неполные</h3>
        <p className="text-amber-600 mt-2 text-sm">AI вернул пустой ответ для этой статьи.</p>
      </div>
    );
  }

  // Publishing Controls Helper
  const PublishControls = ({ platform, label }: { platform: 'wp' | 'vk' | 'telegram', label: string }) => {
     const isScheduled = !!scheduleDate;

     return (
         <div className="mb-4 bg-slate-50 p-3 rounded-lg border border-slate-200">
             <div className="flex items-center justify-between flex-wrap gap-3">
                 <div className="flex items-center gap-2">
                     <span className={`text-xs font-bold ${platform === 'telegram' ? 'text-blue-500' : platform === 'vk' ? 'text-blue-700' : 'text-slate-700'}`}>{label}</span>
                     {pubStatus[platform]?.msg && <span className={`text-[10px] ${pubStatus[platform].success ? 'text-green-600' : 'text-red-600'}`}>{pubStatus[platform].msg}</span>}
                 </div>

                 <div className="flex items-center gap-2">
                    <input 
                        type="datetime-local" 
                        value={scheduleDate}
                        onChange={(e) => setScheduleDate(e.target.value)}
                        className="text-xs border border-slate-300 rounded px-2 py-1.5 bg-white text-slate-600 focus:ring-2 focus:ring-brand-orange outline-none w-36"
                        title="Выберите дату для отложенной публикации"
                    />

                    <button 
                        onClick={() => handlePublish(platform)}
                        disabled={!!publishing}
                        className={`text-white text-xs px-4 py-1.5 rounded font-bold disabled:opacity-50 transition-colors uppercase tracking-wider ${
                            isScheduled
                            ? 'bg-purple-600 hover:bg-purple-700' 
                            : 'bg-brand-orange hover:bg-orange-600'
                        }`}
                    >
                        {publishing === platform ? '...' : (isScheduled ? 'Отложить' : 'Опубликовать')}
                    </button>
                 </div>
             </div>
         </div>
     );
  };

  return (
    <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-200 flex flex-col h-full">
      {/* Header / Tabs */}
      <div className="bg-slate-50 border-b border-slate-200 p-2 flex justify-between items-center">
        <div className="flex space-x-1 overflow-x-auto">
          {(['site', 'telegram', 'vk', 'prompts'] as const).map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`px-3 py-1.5 text-xs font-bold rounded-md uppercase tracking-wider transition-colors whitespace-nowrap ${
                activeTab === tab 
                  ? 'bg-white text-brand-orange shadow-sm border border-slate-200' 
                  : 'text-brand-grey hover:bg-slate-100 hover:text-brand-dark'
              }`}
            >
              {tabLabels[tab]}
            </button>
          ))}
        </div>
        <button 
           onClick={() => {
             if (activeTab === 'site') copyContent(pack.siteArticle.content);
             if (activeTab === 'telegram') copyContent(pack.telegramPost.content);
             if (activeTab === 'vk') copyContent(pack.vkPost.content);
           }} 
           className="text-slate-400 hover:text-brand-orange px-3 py-1 text-sm rounded hover:bg-slate-100 transition-colors"
           title="Скопировать весь текст"
        >
           {copied ? '✓' : '📋'}
        </button>
      </div>

      {/* Content Area */}
      <div className="p-6 overflow-y-auto flex-1 custom-scrollbar">
        {activeTab === 'site' && (
          <article className="max-w-none pr-8">
            <PublishControls platform="wp" label="WordPress" />

            {/* Meta Box */}
            <div className="bg-slate-50 border border-slate-200 p-3 rounded-lg mb-6 text-xs text-brand-grey">
               <p><span className="font-bold text-brand-dark">META:</span> {pack.metaDescription}</p>
               <p className="mt-1"><span className="font-bold text-brand-dark">Tags:</span> {pack.siteArticle.hashtags}</p>
            </div>

            <h1 className="text-3xl font-bold font-serif-custom text-brand-dark leading-tight mb-6">
                {pack.siteArticle.headline}
            </h1>

            {/* 3 Images Grid */}
            <div className="grid grid-cols-3 gap-2 mb-8">
                 {pack.generatedImages.slice(0, 3).map((img, idx) => (
                   <div key={idx} className="relative aspect-square group">
                     <img src={img} alt={`Img ${idx}`} className="w-full h-full object-cover rounded-lg shadow-sm border border-slate-100" />
                     <span className="absolute bottom-1 right-1 bg-black/70 text-white text-[10px] px-1 rounded font-bold">IMG {idx+1}</span>
                     <button 
                        onClick={() => {
                            const link = document.createElement('a');
                            link.href = img;
                            link.download = `image-${idx}.png`;
                            link.click();
                        }}
                        className="absolute top-1 right-1 bg-white/90 p-1.5 rounded-full opacity-0 group-hover:opacity-100 transition-opacity hover:bg-white text-brand-orange"
                        title="Скачать"
                     >
                         ⬇
                     </button>
                   </div>
                 ))}
            </div>

            <div className="prose-lg text-slate-700">
               <ReactMarkdown components={{
                   blockquote: ({node, children}: any) => (
                    <blockquote className="relative p-6 pl-8 bg-orange-50/50 border-l-4 border-brand-orange rounded-r-lg italic text-slate-800 font-serif-custom text-lg my-8">
                        <span className="absolute top-2 left-2 text-orange-300 text-4xl leading-none select-none">“</span>
                        {children}
                    </blockquote>
                   ),
                   h2: ({node, children}: any) => (
                     <h2 className="text-xl font-bold text-brand-dark font-sans border-b border-orange-200 pb-2 inline-block pr-8 mt-8 mb-4">
                        {children}
                     </h2>
                   ),
                   p: ({node, children}: any) => <p className="mb-4 leading-relaxed font-serif-custom text-slate-800">{children}</p>,
                   ul: ({node, children}: any) => <ul className="list-disc pl-5 mb-4 space-y-2 text-slate-700">{children}</ul>,
                   li: ({node, children}: any) => <li className="pl-1">{children}</li>,
                   strong: ({node, children}: any) => <strong className="font-bold text-brand-dark">{children}</strong>,
               }}>
                   {pack.siteArticle.content}
               </ReactMarkdown>
            </div>
          </article>
        )}

        {activeTab === 'telegram' && (
          <div className="max-w-md mx-auto h-full flex flex-col">
             <div className="bg-[#f0f2f5] p-4 rounded-lg shadow-sm border border-[#dfe3e7] flex-1">
                <div className="flex items-center space-x-2 mb-3">
                    <div className="w-6 h-6 bg-blue-500 rounded-full flex items-center justify-center text-white font-bold text-[10px]">TG</div>
                    <span className="font-bold text-slate-800 text-xs">Telegram Preview</span>
                </div>

                <PublishControls platform="telegram" label="Канал" />

                {pack.generatedImages[0] && (
                  <img src={pack.generatedImages[0]} alt="Post" className="w-full h-40 object-cover rounded-lg mb-3" />
                )}
                <div className="whitespace-pre-wrap text-slate-800 text-sm leading-relaxed font-sans bg-white p-3 rounded border border-slate-200 shadow-sm">
                  {pack.telegramPost.content}
                </div>
             </div>
          </div>
        )}

        {activeTab === 'vk' && (
          <div className="max-w-md mx-auto h-full flex flex-col">
             <div className="bg-white p-4 rounded-lg border border-slate-200 flex-1">
               <div className="flex items-center space-x-2 mb-3">
                   <div className="w-6 h-6 bg-blue-600 rounded-full flex items-center justify-center text-white font-bold text-[10px]">VK</div>
                   <span className="font-bold text-blue-700 text-xs">VKontakte Preview</span>
               </div>

               <PublishControls platform="vk" label="Стена сообщества" />

                <div className="whitespace-pre-wrap text-slate-800 text-sm mb-3 font-sans">
                  {pack.vkPost.content}
                </div>
                {pack.generatedImages[1] ? (
                  <img src={pack.generatedImages[1]} alt="VK" className="w-full h-48 object-cover rounded" />
                ) : (pack.generatedImages[0] && <img src={pack.generatedImages[0]} alt="VK" className="w-full h-48 object-cover rounded" />)}
             </div>
          </div>
        )}

        {activeTab === 'prompts' && (
          <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 h-full overflow-y-auto">
             <h3 className="font-bold text-brand-dark mb-3 text-sm">Промпты для Midjourney/AI</h3>
             <ul className="space-y-4">
               {pack.imagePrompts.slice(0,3).map((prompt, i) => (
                 <li key={i} className="text-xs text-slate-600 font-mono bg-white p-3 rounded border border-slate-200 shadow-sm relative group">
                   <span className="absolute top-2 right-2 text-slate-300 font-bold">{i+1}</span>
                   {prompt}
                   <button 
                     onClick={() => {navigator.clipboard.writeText(prompt);}}
                     className="mt-2 text-[10px] text-brand-orange hover:underline block"
                   >
                     Копировать промпт
                   </button>
                 </li>
               ))}
             </ul>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { DigestData, PublishingConfig } from '../types';
import { publishToTelegram, publishToVK } from '../services/publishingService';

interface DigestPostViewerProps {
  digest: DigestData;
  pubConfig: PublishingConfig;
}

export const DigestPostViewer: React.FC<DigestPostViewerProps> = ({ digest, pubConfig }) => {
  const [activeView, setActiveView] = useState<'long' | 'short'>('long');
  const [copied, setCopied] = useState(false);
  const [publishing, setPublishing] = useState<string | null>(null);
  const [pubStatus, setPubStatus] = useState<{ [key: string]: { success: boolean; msg: string } }>({});

  const getTextToUse = () => activeView === 'long' ? digest.formattedDigestText : digest.formattedShortDigest;

  const handleCopy = () => {
    navigator.clipboard.writeText(getTextToUse());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handlePublish = async (platform: 'telegram' | 'vk') => {
    setPublishing(platform);
    setPubStatus(prev => ({ ...prev, [platform]: { success: false, msg: '' } }));

    const textToSend = getTextToUse();
    // Use image only for Long format
    const imageToSend = activeView === 'long' ? digest.collageImage : undefined;

    try {
      if (platform === 'telegram') {
        await publishToTelegram(pubConfig, textToSend, imageToSend);
        setPubStatus(prev => ({ ...prev, telegram: { success: true, msg: 'Отправлено!' } }));
      }
      else if (platform === 'vk') {
        await publishToVK(pubConfig, textToSend, imageToSend);
        setPubStatus(prev => ({ ...prev, vk: { success: true, msg: 'Опубликовано!' } }));
      }
    } catch (e: any) {
      setPubStatus(prev => ({ ...prev, [platform]: { success: false, msg: e.message } }));
    } finally {
      setPublishing(null);
    }
  };

  return (
    <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-200 h-full flex flex-col">
      <div className="bg-slate-50 border-b border-slate-200 p-3 flex justify-between items-center">
        <div className="flex gap-2">
            <button 
                onClick={() => setActiveView('long')}
                className={`text-xs px-3 py-1.5 rounded-md font-bold uppercase transition-colors tracking-wide ${activeView === 'long' ? 'bg-white shadow-sm text-brand-orange border border-slate-200' : 'text-brand-grey hover:bg-slate-100'}`}
            >
                Полный Дайджест
            </button>
            <button 
                onClick={() => setActiveView('short')}
                className={`text-xs px-3 py-1.5 rounded-md font-bold uppercase transition-colors tracking-wide ${activeView === 'short' ? 'bg-white shadow-sm text-brand-orange border border-slate-200' : 'text-brand-grey hover:bg-slate-100'}`}
            >
                Бегущая строка
            </button>
        </div>
        <button 
          onClick={handleCopy}
          className={`text-xs px-3 py-1 rounded transition-colors uppercase font-bold ${copied ? 'bg-green-100 text-green-700' : 'bg-orange-100 text-brand-orange hover:bg-orange-200'}`}
        >
          {copied ? 'Скопировано!' : 'Копировать'}
        </button>
      </div>

      <div className="p-0 overflow-y-auto custom-scrollbar flex-1 relative flex flex-col">
        {/* Collage Image Section (Only for Long view) */}
        {activeView === 'long' && (
            <div className="relative h-64 w-full bg-slate-100 group shrink-0">
            {digest.collageImage ? (
                <img 
                src={digest.collageImage} 
                alt="Daily Digest Collage" 
                className="w-full h-full object-cover transition-transform duration-700 hover:scale-105"
                />
            ) : (
                <div className="w-full h-full flex items-center justify-center text-slate-400 text-sm">
                    Генерация коллажа...
                </div>
            )}
            <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-brand-dark/80 to-transparent p-4">
                <span className="text-white font-bold text-lg drop-shadow-md font-sans uppercase">Новости Туризма</span>
            </div>
            </div>
        )}

        {/* Action Buttons */}
        <div className="grid grid-cols-2 gap-2 p-4 bg-slate-50 border-b border-slate-100 shrink-0">
           <div className="flex flex-col items-center">
              <button 
                 onClick={() => handlePublish('telegram')}
                 disabled={!!publishing}
                 className="w-full bg-blue-500 text-white text-xs font-bold py-2 rounded hover:bg-blue-600 disabled:opacity-50 mb-1 uppercase tracking-wider"
              >
                 {publishing === 'telegram' ? '...' : `В Telegram (${activeView === 'short' ? 'Текст' : 'Фото+Текст'})`}
              </button>
              {pubStatus.telegram?.msg && <span className={`text-[10px] ${pubStatus.telegram.success ? 'text-green-600' : 'text-red-600'}`}>{pubStatus.telegram.msg}</span>}
           </div>
           <div className="flex flex-col items-center">
              <button 
                 onClick={() => handlePublish('vk')}
                 disabled={!!publishing}
                 className="w-full bg-blue-600 text-white text-xs font-bold py-2 rounded hover:bg-blue-700 disabled:opacity-50 mb-1 uppercase tracking-wider"
              >
                 {publishing === 'vk' ? '...' : `В ВК (${activeView === 'short' ? 'Текст' : 'Фото+Текст'})`}
              </button>
              {pubStatus.vk?.msg && <span className={`text-[10px] ${pubStatus.vk.success ? 'text-green-600' : 'text-red-600'}`}>{pubStatus.vk.msg}</span>}
           </div>
        </div>

        {/* Text Content */}
        <div className="p-6 flex-1">
          <div className="bg-[#f0f2f5] p-4 rounded-xl border border-slate-200 shadow-inner h-full overflow-y-auto">
             <pre className="whitespace-pre-wrap font-sans text-sm text-slate-800 leading-relaxed">
               {getTextToUse()}
             </pre>
          </div>

          {activeView === 'long' && (
            <div className="mt-4 pt-4 border-t border-slate-100 text-xs text-brand-grey">
                <p className="mb-1 font-semibold">Промпт для коллажа:</p>
                <p className="font-mono bg-slate-50 p-2 rounded">{digest.collagePrompt}</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

