}

export enum AppState {
  IDLE = 'IDLE',
  SEARCHING = 'SEARCHING',
  SELECTING = 'SELECTING',
  GENERATING_CONTENT = 'GENERATING_CONTENT',
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR'
}

export interface PublishingConfig {
  telegramBotToken: string;
  telegramChatId: string;
  vkAccessToken: string;
  vkOwnerId: string;
  wpUrl: string;
  wpUsername: string;
  wpAppPassword: string;
}

import { GoogleGenAI } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

// Инициализация AI через переменную окружения
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

const cleanJsonResponse = (text: string) => {
  return text.replace(/```json/g, "").replace(/```/g, "").replace(/\\n/g, " ").trim();
};

/**
 * Поиск и сбор 10 новостей туризма за последние 48 часов
 */
export const fetchRealNews = async (): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — ГЛАВНЫЙ АНАЛИТИК ИЗДАНИЯ "ПЕРВЫЙ ТУРИСТИЧЕСКИЙ". 
    ТВОЯ ЗАДАЧА: Собрать ровно 10 самых актуальных новостей туризма.

    КРИТИЧЕСКИЕ ПРАВИЛА:
    1. ВРЕМЯ: Только новости, опубликованные за последние 48 часов. СТАРЫЕ НОВОСТИ ЗАПРЕЩЕНЫ.
    2. КОЛИЧЕСТВО: Ровно 10 новостей.
    3. СТРУКТУРА НОВОСТИ: Заголовок и пояснение (СТРОГО 1-2 предложения сути).
    4. БЕГУЩАЯ СТРОКА (ticker): [Эмодзи] [ЗАГОЛОВОК]. [Краткое пояснение].
    5. СТИЛЬ: Тонкая ирония, достоверность. Никакого первого лица ("Я", "Мы"). Только от лица "Первого Туристического".

    ВЕРНИ ТОЛЬКО ЧИСТЫЙ JSON:
    {
      "news": [
        { "id": "id", "title": "Заголовок", "summary": "Пояснение в 1-2 предложениях.", "location": "Место", "ticker": "✈️ ЗАГОЛОВОК. Суть кратко." }
      ],
      "formattedDigestText": "Полный текст дайджеста для Telegram. В начале: 'ТУРИСТИЧЕСКИЙ ВЕСТНИК'. Список из 10 новостей. Стиль: Ироничный отчет редакции.",
      "formattedShortDigest": "Склеенная бегущая строка из всех полей ticker через ' • '",
      "collagePrompt": "Photorealistic 8k travel collage prompt, no text"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Найди 10 новостей туризма за последние 48 часов на ${today}. Используй Google Search для проверки дат.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json"
      }
    });

    const cleaned = cleanJsonResponse(response.text || "");
    const data = JSON.parse(cleaned);

    // Гарантируем уникальные ID
