/**
 * Генерация фотореалистичных изображений
 */
export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { 
        parts: [{ text: `High-end professional RAW photography, hyper-realistic, 8k resolution, cinematic lighting, shot on Sony A7R IV, highly detailed travel scene: ${prompt} --no illustration, painting, cartoon, cgi, 3d, text` }] 
      },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch (err) {
    console.warn("Image generation failed", err);
    return "";
  }
};

