                      <div key={i} className="group relative overflow-hidden rounded-[2rem] shadow-xl border border-slate-100">
                        <img src={img} className="w-full aspect-[16/9] object-cover transition-transform duration-700 group-hover:scale-105" alt={`Иллюстрация ${i+1}`} />
                        <div className="absolute bottom-4 right-4 bg-brand-dark/50 backdrop-blur-md text-white text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-widest">Кадр №{i+1}</div>
                      </div>
                    ))}
                  </div>

                  <div className="prose prose-slate prose-lg max-w-none text-slate-800 leading-loose">
                    <ReactMarkdown>{content}</ReactMarkdown>
                  </div>

                  <div className="mt-12 pt-8 border-t border-slate-100 flex items-center gap-4">
                    <span className="text-[10px] font-black text-brand-orange uppercase tracking-[0.3em]">Редакция:</span>
                    <div className="flex gap-2">
                       {hashtags.split(',').map((t, idx) => (
                         <span key={idx} className="bg-slate-100 text-slate-500 text-[9px] font-bold px-3 py-1 rounded-full uppercase">#{t.trim()}</span>
                       ))}
                    </div>
                  </div>
                </article>
              )}
            </div>
          </div>
        )}

        {activeTab === 'telegram' && (
          <div className="max-w-md mx-auto space-y-6">
             <PublishControls platform="telegram" label="Telegram Канал" />
             {isEditing ? (
               <textarea value={tgText} onChange={e => setTgText(e.target.value)} className="w-full h-80 p-6 text-sm border border-slate-200 rounded-2xl outline-none" />
             ) : (
               <div className="bg-[#f0f2f5] p-6 rounded-3xl text-sm whitespace-pre-wrap leading-relaxed shadow-inner border border-slate-200/50 text-slate-700">
                  {tgText}
               </div>
             )}
          </div>
        )}

        {activeTab === 'vk' && (
          <div className="max-w-md mx-auto space-y-6">
             <PublishControls platform="vk" label="ВКонтакте Группа" />
