  const [vkText, setVkText] = useState(pack.vkPost?.content || '');

  const [publishing, setPublishing] = useState<string | null>(null);
  const [pubStatus, setPubStatus] = useState<{ [key: string]: { success: boolean; msg: string } }>({});
  const [scheduleDate, setScheduleDate] = useState<string>('');

  useEffect(() => {
    setHeadline(pack.siteArticle?.headline || '');
    setContent(pack.siteArticle?.content || '');
    setHashtags(pack.siteArticle?.hashtags || '');
    setMetaDesc(pack.metaDescription || '');
    setTgText(pack.telegramPost?.content || '');
    setVkText(pack.vkPost?.content || '');
  }, [pack]);

  const handlePublish = async (platform: 'telegram' | 'vk' | 'wp') => {
    setPublishing(platform);
    const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;

    try {
      if (platform === 'telegram') {
        await publishToTelegram(pubConfig, tgText, pack.generatedImages[0], dateObj);
      } else if (platform === 'vk') {
        await publishToVK(pubConfig, vkText, pack.generatedImages[0], dateObj);
      } else if (platform === 'wp') {
        await publishToWordPress(pubConfig, headline, content, pack.generatedImages, hashtags, dateObj, metaDesc);
      }
      setPubStatus(prev => ({ ...prev, [platform]: { success: true, msg: 'Опубликовано!' } }));
    } catch (e: any) {
      setPubStatus(prev => ({ ...prev, [platform]: { success: false, msg: e.message } }));
    } finally {
      setPublishing(null);
    }
  };

  const PublishControls = ({ platform, label }: { platform: 'wp' | 'vk' | 'telegram', label: string }) => (
    <div className="mb-6 bg-slate-50 p-4 rounded-xl border border-slate-100 flex items-center justify-between">
      <div className="flex flex-col">
        <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">{label}</span>
        {pubStatus[platform]?.msg && <span className={`text-[10px] font-bold ${pubStatus[platform].success ? 'text-green-600' : 'text-red-600'}`}>{pubStatus[platform].msg}</span>}
      </div>
      <div className="flex items-center gap-3">
        <input type="datetime-local" value={scheduleDate} onChange={(e) => setScheduleDate(e.target.value)} className="text-[10px] border border-slate-200 rounded px-2 py-1.5 bg-white outline-none focus:ring-1 focus:ring-brand-orange" />
        <button onClick={() => handlePublish(platform)} disabled={!!publishing} className="bg-brand-orange text-white text-[10px] px-4 py-2 rounded-lg font-black uppercase hover:bg-orange-600 disabled:opacity-50 transition-all shadow-md shadow-orange-100">
          {publishing === platform ? '...' : (scheduleDate ? 'Запланировать' : 'В эфир')}
        </button>
      </div>
    </div>
  );

  if (pack.error) return <div className="p-10 text-center text-red-500 font-bold">{pack.error}</div>;

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl overflow-hidden border border-slate-100 flex flex-col h-full animate-fade-in">
      <div className="bg-brand-dark border-b border-white/5 p-3 flex justify-between items-center">
        <div className="flex space-x-2">
          {['site', 'telegram', 'vk', 'prompts'].map((tab) => (
            <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-4 py-2 text-[10px] font-black rounded-lg uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-brand-orange text-white shadow-lg shadow-orange-500/20' : 'text-slate-400 hover:text-white'}`}>
              {tab === 'site' ? 'Статья' : tab === 'telegram' ? 'TG' : tab === 'vk' ? 'VK' : 'Промпты'}
            </button>
          ))}
        </div>
        <button onClick={() => setIsEditing(!isEditing)} className={`px-4 py-2 text-[10px] font-black rounded-lg uppercase border transition-all ${isEditing ? 'bg-white text-brand-dark' : 'text-white border-white/20 hover:border-white'}`}>
          {isEditing ? 'Сохранить' : 'Править'}
        </button>
      </div>

      <div className="p-8 overflow-y-auto flex-1 custom-scrollbar">
        {activeTab === 'site' && (
          <div className="space-y-6">
            <PublishControls platform="wp" label="WordPress Издание" />

            <div className="space-y-6">
              {isEditing ? (
                <>
                  <input value={headline} onChange={e => setHeadline(e.target.value)} className="w-full text-3xl font-black font-serif-custom border-b-2 border-slate-100 outline-none focus:border-brand-orange pb-2" placeholder="Заголовок..." />
                  <textarea value={metaDesc} onChange={e => setMetaDesc(e.target.value)} className="w-full text-xs p-3 bg-slate-50 rounded-xl border border-slate-200 italic" rows={2} placeholder="SEO описание..." />
                  <textarea value={content} onChange={e => setContent(e.target.value)} className="w-full h-96 p-6 text-base font-serif-custom border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-brand-orange/20" placeholder="Текст (Markdown)..." />
                  <div className="flex items-center gap-3 bg-slate-50 p-3 rounded-xl">
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Теги:</span>
                    <input value={hashtags} onChange={e => setHashtags(e.target.value)} className="flex-1 bg-transparent text-xs outline-none font-bold" placeholder="тег1, тег2..."/>
                  </div>
                </>
              ) : (
                <article className="article-font max-w-none">
                  <h1 className="text-4xl font-black text-brand-dark leading-tight mb-4">{headline}</h1>
                  <div className="bg-orange-50/50 p-4 rounded-2xl text-sm italic text-slate-600 mb-8 border-l-4 border-brand-orange leading-relaxed">
                    {metaDesc}
                  </div>

                  <div className="prose prose-slate prose-lg max-w-none text-slate-800 leading-loose">
                    <ReactMarkdown components={{
                        h2: ({node, ...props}) => <h2 className="text-2xl font-black text-brand-dark border-b-2 border-orange-100 pb-2 mt-10 mb-6 uppercase tracking-tight" {...props} />,
                        blockquote: ({node, ...props}) => <blockquote className="border-l-4 border-brand-orange bg-slate-50 p-6 italic rounded-r-2xl my-8 text-slate-700 shadow-sm" {...props} />,
                        strong: ({node, ...props}) => <strong className="font-black text-brand-dark" {...props} />,
                    }}>
