                    </ReactMarkdown>
                  </div>

                  {/* Иллюстрации в конце статьи как фотоотчет */}
                  <div className="grid grid-cols-1 gap-8 my-12">
                    {pack.generatedImages.map((img, i) => img && (
                      <div key={i} className="group relative overflow-hidden rounded-[2rem] shadow-xl border border-slate-100">
