import { GoogleGenAI } from "@google/genai";
import { DigestData, GeneratedContentPack, NewsItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

const getCurrentDate = () => {
  return new Date().toLocaleDateString('ru-RU', { day: 'numeric', month: 'long', year: 'numeric' });
};

const cleanJsonResponse = (text: string) => {
  return text.replace(/```json/g, "").replace(/```/g, "").replace(/\\n/g, " ").trim();
};

/**
 * Сбор 10 новостей туризма за последние 48 часов (фокус на РФ и российских туристов)
 */
export const fetchRealNews = async (): Promise<DigestData> => {
  const model = "gemini-3-flash-preview"; 
  const today = getCurrentDate();

  const systemInstruction = `
    ТЫ — ВЕДУЩИЙ АНАЛИТИК "ПЕРВОГО ТУРИСТИЧЕСКОГО". 
    ЗАДАЧА: Собрать ровно 10 новостей туризма за последние 48 часов.

    КРИТЕРИИ (СТРОГО):
    1. РЕЛЕВАНТНОСТЬ: Только Россия (внутренний туризм) или мир в контексте российских туристов (визы, рейсы из РФ, правила в Турции, Египте, Таиланде, ОАЭ, Европе).
    2. ВРЕМЯ: Только последние 48 часов. Старые новости игнорировать.
    3. ФОРМАТ: Заголовок и пояснение (1-2 предложения сути).
    4. БЕГУЩАЯ СТРОКА: [Эмодзи] [ЗАГОЛОВОК]. [Краткая суть].

    ВЕРНИ JSON:
    {
      "news": [
        { "id": "id", "title": "Заголовок", "summary": "Пояснение (1-2 предложения).", "location": "РФ/Мир", "ticker": "✈️ ЗАГОЛОВОК. Суть." }
      ],
      "formattedDigestText": "Дайджест для Telegram (10 новостей). Заголовок: ТУРИСТИЧЕСКИЙ ВЕСТНИК. Стиль: Редакция сообщает.",
      "formattedShortDigest": "Строка через ' • '",
      "collagePrompt": "Photorealistic 8k travel collage, suitcases at airport, no text"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Найди 10 новостей туризма для россиян за последние 48 часов на ${today}. Используй Google Search для проверки фактов.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json"
      }
    });

    const data = JSON.parse(cleanJsonResponse(response.text || ""));
    data.news = data.news.map((n: any, i: number) => ({...n, id: `news-${Date.now()}-${i}`}));
    return data;
  } catch (error) {
    console.error("News Fetch Error:", error);
    throw new Error("Не удалось собрать новости.");
  }
};

/**
 * Генерация статьи без первого лица, без markdown-разметки, структурированно
 */
export const generateArticleZhvanetsky = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview";

  const systemInstruction = `
    ТЫ — КОЛУМНИСТ "ПЕРВОГО ТУРИСТИЧЕСКОГО". 
    СТИЛЬ: Михаил Жванецкий. Тонкий юмор, ирония, лаконичность.

    ПРАВИЛА ТЕКСТА:
    1. ОТ ЛИЦА РЕДАКЦИИ: Никаких "Я" или "Мы". Используй безличные формы или "Редакция".
    2. БЕЗ MARKDOWN: В текстах разделов (body) КАТЕГОРИЧЕСКИ ЗАПРЕЩЕНЫ любые знаки разметки типа ##, **, __, *. Текст должен быть абсолютно чистым.
    3. СТРУКТУРА: Раздели статью на логические разделы (sections). Каждый раздел имеет heading (подзаголовок) и body (текст).
    4. ХЕШТЕГИ: 
       - В поле "siteArticle.hashtags": слова через запятую БЕЗ знака # (например: туризм, сочи).
       - В полях "telegramPost" и "vkPost": В конце текста добавь теги СО знаком # через запятую.
    5. ПРОВЕРКА: Только реальные факты последних 48 часов.

    ВЕРНИ JSON СЛЕДУЮЩЕЙ СТРУКТУРЫ:
    {
      "siteArticle": { 
        "headline": "Заголовок статьи", 
        "sections": [
           { "heading": "Подзаголовок", "body": "Текст раздела без разметки" }
        ],
        "hashtags": "слово, слово" 
      },
      "telegramPost": { "content": "Текст поста для ТГ с #хештегами" },
      "vkPost": { "content": "Текст поста для ВК с #хештегами" },
      "imagePrompts": ["photo prompt 1", "photo prompt 2", "photo prompt 3"],
      "metaDescription": "SEO описание"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Тема: ${newsItem.title}. Факты: ${newsItem.summary}. Напиши статью от лица редакции. Подзаголовки обязательны в структуре JSON. Никаких ** или ## в тексте.`,
      config: { 
        tools: [{ googleSearch: {} }],
        systemInstruction, 
        responseMimeType: "application/json" 
      }
    });

    const parsed = JSON.parse(cleanJsonResponse(response.text || ""));
    return { newsId: newsItem.id, ...parsed };
  } catch (error) {
    console.error("Article generation error", error);
    throw new Error("Ошибка генерации статьи.");
  }
};

export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `Professional travel photography, 8k, hyper-realistic: ${prompt} --no illustration, text, painting` }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch { return ""; }
};

export const generateImagesForArticle = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
    const img = await generateImage(p);
    if (img) images.push(img);
    await new Promise(r => setTimeout(r, 2000)); 
  }
  while(images.length < 3) images.push(""); 
  return images;
};

import React, { useState, useEffect } from 'react';
import { GeneratedContentPack, PublishingConfig, ArticleSection } from '../types';
import { publishToTelegram, publishToVK, publishToWordPress } from '../services/publishingService';

interface ResultViewerProps {
  pack: GeneratedContentPack;
  pubConfig: PublishingConfig;
}

export const ResultViewer: React.FC<ResultViewerProps> = ({ pack, pubConfig }) => {
  const [activeTab, setActiveTab] = useState<'site' | 'telegram' | 'vk' | 'prompts'>('site');
  const [isEditing, setIsEditing] = useState(false);

  const [headline, setHeadline] = useState(pack.siteArticle?.headline || '');
  const [sections, setSections] = useState<ArticleSection[]>(pack.siteArticle?.sections || []);
  const [hashtags, setHashtags] = useState(pack.siteArticle?.hashtags || '');
  const [metaDesc, setMetaDesc] = useState(pack.metaDescription || '');
  const [tgText, setTgText] = useState(pack.telegramPost?.content || '');
  const [vkText, setVkText] = useState(pack.vkPost?.content || '');

  const [publishing, setPublishing] = useState<string | null>(null);
  const [pubStatus, setPubStatus] = useState<{ [key: string]: { success: boolean; msg: string } }>({});

  useEffect(() => {
    setHeadline(pack.siteArticle?.headline || '');
    setSections(pack.siteArticle?.sections || []);
    setHashtags(pack.siteArticle?.hashtags || '');
    setMetaDesc(pack.metaDescription || '');
    setTgText(pack.telegramPost?.content || '');
    setVkText(pack.vkPost?.content || '');
  }, [pack]);

  const handlePublish = async (platform: 'telegram' | 'vk' | 'wp') => {
    setPublishing(platform);
    // Для WP собираем текст из секций
    const fullContent = sections.map(s => `${s.heading}\n\n${s.body}`).join('\n\n');

    try {
      if (platform === 'telegram') await publishToTelegram(pubConfig, tgText, pack.generatedImages[0]);
      else if (platform === 'vk') await publishToVK(pubConfig, vkText, pack.generatedImages[0]);
      else if (platform === 'wp') await publishToWordPress(pubConfig, headline, fullContent, pack.generatedImages, hashtags, undefined, metaDesc);
      setPubStatus(prev => ({ ...prev, [platform]: { success: true, msg: 'Опубликовано!' } }));
    } catch (e: any) {
      setPubStatus(prev => ({ ...prev, [platform]: { success: false, msg: e.message } }));
    } finally {
      setPublishing(null);
    }
  };

  const handleSectionChange = (index: number, field: 'heading' | 'body', value: string) => {
    const newSections = [...sections];
    newSections[index][field] = value;
    setSections(newSections);
  };

  if (pack.error) return <div className="p-10 text-center text-red-500 font-bold">{pack.error}</div>;

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl overflow-hidden border border-slate-100 flex flex-col h-full animate-fade-in mb-10">
      <div className="bg-brand-dark border-b border-white/5 p-3 flex justify-between items-center">
        <div className="flex space-x-2">
          {['site', 'telegram', 'vk', 'prompts'].map((tab) => (
            <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-4 py-2 text-[10px] font-black rounded-lg uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-brand-orange text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}>
              {tab === 'site' ? 'Статья' : tab === 'telegram' ? 'TG' : tab === 'vk' ? 'VK' : 'Промпты'}
            </button>
          ))}
        </div>
        <button onClick={() => setIsEditing(!isEditing)} className={`px-4 py-2 text-[10px] font-black rounded-lg uppercase border transition-all ${isEditing ? 'bg-white text-brand-dark' : 'text-white border-white/20'}`}>
          {isEditing ? 'Сохранить' : 'Править'}
        </button>
      </div>

      <div className="p-8 overflow-y-auto flex-1 custom-scrollbar">
        {activeTab === 'site' && (
          <div className="space-y-6">
            <div className="flex gap-2">
               <button onClick={() => handlePublish('wp')} disabled={!!publishing} className="bg-brand-orange text-white text-[10px] px-4 py-2 rounded-lg font-black uppercase hover:bg-orange-600">
                  {publishing === 'wp' ? '...' : 'Опубликовать на сайт'}
               </button>
               {pubStatus.wp?.msg && <span className={`text-[10px] self-center font-bold ${pubStatus.wp.success ? 'text-green-600' : 'text-red-600'}`}>{pubStatus.wp.msg}</span>}
            </div>

            <article className="article-font max-w-none">
              {isEditing ? (
                <div className="space-y-4">
                  <input value={headline} onChange={e => setHeadline(e.target.value)} className="w-full p-2 border font-bold text-xl" placeholder="Заголовок" />
                  {sections.map((s, i) => (
                    <div key={i} className="space-y-2 p-4 bg-slate-50 rounded-xl">
                      <input value={s.heading} onChange={e => handleSectionChange(i, 'heading', e.target.value)} className="w-full p-2 border font-bold" placeholder="Подзаголовок" />
                      <textarea value={s.body} onChange={e => handleSectionChange(i, 'body', e.target.value)} className="w-full h-32 p-2 border" placeholder="Текст раздела" />
                    </div>
                  ))}
                  <input value={hashtags} onChange={e => setHashtags(e.target.value)} className="w-full p-2 border italic text-sm" placeholder="Хештеги через запятую (без #)" />
                </div>
              ) : (
                <>
                  <h1 className="text-4xl font-black text-brand-dark leading-tight mb-8">{headline}</h1>
                  <div className="space-y-10 text-slate-800">
                    {sections.map((section, idx) => (
                      <div key={idx} className="space-y-4">
                        {section.heading && <h2 className="text-2xl font-black text-brand-dark uppercase border-b-2 border-orange-100 pb-2">{section.heading}</h2>}
                        <div className="space-y-4">
                          {section.body.split('\n').filter(p => p.trim()).map((para, pIdx) => (
                            <p key={pIdx} className="leading-relaxed text-justify text-lg" style={{ textIndent: '2.5rem' }}>
                              {para.trim()}
                            </p>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>

                  <div className="grid grid-cols-1 gap-8 my-12">
                    {pack.generatedImages.map((img, i) => img && (
                      <img key={i} src={img} className="w-full rounded-[2rem] shadow-2xl border border-slate-100" alt="Иллюстрация редакции" />
                    ))}
                  </div>

                  <div className="mt-8 pt-6 border-t flex items-center gap-3">
                    <span className="text-[10px] font-black text-brand-orange uppercase">Теги:</span>
                    <div className="flex gap-2">
                      {hashtags.split(',').map((t, idx) => (
                        <span key={idx} className="bg-slate-100 text-slate-500 text-[10px] font-bold px-3 py-1 rounded-full uppercase">{t.trim()}</span>
                      ))}
                    </div>
                  </div>
                </>
              )}
            </article>
          </div>
        )}

        {activeTab === 'telegram' && (
          <div className="max-w-md mx-auto space-y-4">
             <button onClick={() => handlePublish('telegram')} disabled={!!publishing} className="w-full bg-blue-500 text-white text-[10px] font-black py-3 rounded-xl uppercase shadow-lg">
                {publishing === 'telegram' ? '...' : 'Отправить в Telegram'}
             </button>
             <div className="bg-[#f0f2f5] p-6 rounded-3xl text-sm whitespace-pre-wrap leading-relaxed shadow-inner border border-slate-200/50 text-slate-700">
