        {activeTab === 'vk' && (
          <div className="max-w-md mx-auto space-y-4">
             <button onClick={() => handlePublish('vk')} disabled={!!publishing} className="w-full bg-blue-600 text-white text-[10px] font-black py-3 rounded-xl uppercase shadow-lg">
                {publishing === 'vk' ? '...' : 'Опубликовать в ВК'}
             </button>
             <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-xl text-sm whitespace-pre-wrap leading-relaxed text-slate-700">
                {vkText}
