        {activeTab === 'prompts' && (
          <div className="space-y-4">
            <h3 className="font-black text-brand-dark text-xs uppercase tracking-widest border-b pb-4">Визуальные задания</h3>
            {pack.imagePrompts.map((p, i) => (
              <div key={i} className="p-4 bg-slate-50 border border-slate-200 rounded-xl text-[11px] font-mono leading-relaxed relative group">
                <span className="bg-brand-orange text-white w-5 h-5 flex items-center justify-center rounded-full text-[9px] font-black absolute -top-2 -left-2">{i+1}</span>
