import React, { useState } from 'react';
import { DigestData, PublishingConfig } from '../types';
import { publishToTelegram, publishToVK } from '../services/publishingService';

interface DigestPostViewerProps {
  digest: DigestData;
  pubConfig: PublishingConfig;
}

export const DigestPostViewer: React.FC<DigestPostViewerProps> = ({ digest, pubConfig }) => {
  const [activeView, setActiveView] = useState<'long' | 'short'>('long');
  const [copied, setCopied] = useState(false);
  const [publishing, setPublishing] = useState<string | null>(null);
  const [pubStatus, setPubStatus] = useState<{ [key: string]: { success: boolean; msg: string } }>({});
  const [scheduleDate, setScheduleDate] = useState<string>('');

  const getTextToUse = () => {
      const rawText = activeView === 'long' ? digest.formattedDigestText : digest.formattedShortDigest;
      return rawText.replace(/\*\*/g, '').replace(/\*/g, '').replace(/__/g, '').trim();
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(getTextToUse());
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDownloadImage = () => {
    if (!digest.collageImage) return;
    const link = document.createElement('a');
    link.href = digest.collageImage;
    link.download = `digest-cover-${Date.now()}.png`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handlePublish = async (platform: 'telegram' | 'vk') => {
    setPublishing(platform);
    const textToSend = getTextToUse();
    const imageToSend = activeView === 'long' ? digest.collageImage : undefined;
    const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;

    try {
      if (platform === 'telegram') await publishToTelegram(pubConfig, textToSend, imageToSend, dateObj);
      else if (platform === 'vk') await publishToVK(pubConfig, textToSend, imageToSend, dateObj);
      setPubStatus(prev => ({ ...prev, [platform]: { success: true, msg: 'Готово!' } }));
    } catch (e: any) {
      setPubStatus(prev => ({ ...prev, [platform]: { success: false, msg: e.message } }));
    } finally {
      setPublishing(null);
    }
  };

  return (
    <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-200 h-full flex flex-col min-h-[600px]">
      <div className="bg-slate-50 border-b p-3 flex justify-between items-center">
        <div className="flex gap-2">
            <button onClick={() => setActiveView('long')} className={`text-[10px] px-3 py-1.5 rounded-lg font-bold uppercase transition-all ${activeView === 'long' ? 'bg-white shadow-sm text-brand-orange' : 'text-slate-400'}`}>Дайджест</button>
            <button onClick={() => setActiveView('short')} className={`text-[10px] px-3 py-1.5 rounded-lg font-bold uppercase transition-all ${activeView === 'short' ? 'bg-white shadow-sm text-brand-orange' : 'text-slate-400'}`}>Строка</button>
        </div>
        <button onClick={handleCopy} className={`text-[10px] px-3 py-1.5 rounded-lg font-black transition-all ${copied ? 'bg-green-500 text-white' : 'bg-brand-orange/10 text-brand-orange'}`}>{copied ? 'OK' : 'КОПИРОВАТЬ'}</button>
      </div>

      <div className="p-0 overflow-y-auto custom-scrollbar flex-1 flex flex-col">
        {activeView === 'long' && (
            <div className="relative h-56 w-full bg-slate-900 shrink-0 group">
            {digest.collageImage ? (
                <>
                  <img src={digest.collageImage} alt="Cover" className="w-full h-full object-cover opacity-80" />
                  <button 
                    onClick={handleDownloadImage}
                    className="absolute top-4 right-4 bg-white/20 backdrop-blur-md hover:bg-white/40 p-2 rounded-lg text-white transition-all opacity-0 group-hover:opacity-100"
                    title="Скачать обложку"
                  >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                    </svg>
                  </button>
                </>
            ) : (
                <div className="w-full h-full flex flex-col items-center justify-center bg-brand-dark">
                    <div className="w-6 h-6 border-2 border-brand-orange border-t-transparent rounded-full animate-spin mb-3"></div>
                    <div className="text-white/30 text-[9px] font-black uppercase tracking-widest">Рисуем обложку выпуска...</div>
                </div>
            )}
            <div className="absolute inset-0 bg-gradient-to-t from-brand-dark to-transparent opacity-60 pointer-events-none"></div>
            <div className="absolute bottom-4 left-5 pointer-events-none">
                <h2 className="text-white font-black text-lg uppercase italic tracking-tight">Эфирный Выпуск</h2>
            </div>
            </div>
        )}

        <div className="p-4 bg-slate-50 border-b space-y-3">
           <input type="datetime-local" value={scheduleDate} onChange={(e) => setScheduleDate(e.target.value)} className="w-full text-xs p-2.5 rounded-xl border border-slate-200 outline-none font-mono" />
           <div className="grid grid-cols-2 gap-2">
              <button onClick={() => handlePublish('telegram')} disabled={!!publishing} className="bg-blue-500 text-white text-[10px] font-black py-3 rounded-xl uppercase tracking-widest shadow-md">{publishing === 'telegram' ? '...' : 'TG'}</button>
              <button onClick={() => handlePublish('vk')} disabled={!!publishing} className="bg-blue-600 text-white text-[10px] font-black py-3 rounded-xl uppercase tracking-widest shadow-md">{publishing === 'vk' ? '...' : 'VK'}</button>
           </div>
           {Object.values(pubStatus).some((s: any) => s.msg) && (
               <p className="text-[9px] text-center font-bold text-slate-400 uppercase">Статус: {Object.values(pubStatus).map((s: any) => s.msg).filter(Boolean).join(' | ')}</p>
           )}
        </div>

        <div className="p-6 flex-1 bg-white">
          {activeView === 'short' ? (
              <div className="bg-brand-dark p-6 rounded-2xl border-l-4 border-brand-orange shadow-lg">
                  <div className="text-brand-orange font-mono text-sm leading-relaxed whitespace-pre-wrap">{getTextToUse()}</div>
              </div>
          ) : (
              <div className="whitespace-pre-wrap font-sans text-sm text-slate-700 leading-relaxed font-medium">{getTextToUse()}</div>
          )}
        </div>
      </div>
    </div>
  );
};

