  const systemInstruction = `
    ТЫ — ВЕДУЩИЙ АНАЛИТИК "ПЕРВОГО ТУРИСТИЧЕСКОГО". 
    ЗАДАЧА: Собрать ровно 10 новостей туризма за последние 48 часов.

    КРИТЕРИИ (СТРОГО):
    1. РЕЛЕВАНТНОСТЬ: Только Россия (внутренний туризм) или мир в контексте российских туристов (визы, рейсы из РФ, правила в Турции, Египте, Таиланде, ОАЭ, Европе).
    2. ВРЕМЯ: Только последние 48 часов.
    3. ФОРМАТ: Заголовок и пояснение (1-2 предложения сути).
    4. БЕГУЩАЯ СТРОКА: [Эмодзи] [ЗАГОЛОВОК]. [Краткая суть].

    ВЕРНИ JSON:
    {
      "news": [
        { "id": "id", "title": "Заголовок", "summary": "Пояснение.", "location": "РФ/Мир", "ticker": "✈️ ЗАГОЛОВОК. Суть." }
      ],
      "formattedDigestText": "Дайджест для Telegram (10 новостей).",
      "formattedShortDigest": "Строка через ' • '",
      "collagePrompt": "Photorealistic 8k travel collage, suitcases at airport, cinematic lighting, no text"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Найди 10 новостей туризма для россиян за последние 48 часов на ${today}. Используй Google Search.`,
      config: {
        tools: [{ googleSearch: {} }],
        systemInstruction,
        responseMimeType: "application/json"
      }
    });

    const data = JSON.parse(cleanJsonResponse(response.text || ""));
    data.news = data.news.map((n: any, i: number) => ({...n, id: `news-${Date.now()}-${i}`}));
    return data;
  } catch (error) {
    console.error("News Fetch Error:", error);
    throw new Error("Не удалось собрать новости.");
  }
};

/**
 * Генерация статьи объемом 3000-3500 знаков в стиле Жванецкого
 */
export const generateArticleZhvanetsky = async (newsItem: NewsItem): Promise<Omit<GeneratedContentPack, 'generatedImages'>> => {
  const model = "gemini-3-pro-preview";

  const systemInstruction = `
    ТЫ — ВЕДУЩИЙ КОЛУМНИСТ "ПЕРВОГО ТУРИСТИЧЕСКОГО". 
    СТИЛЬ: Михаил Жванецкий. Тонкая ирония, парадоксальные выводы, философский взгляд на чемоданы и границы.

    ПРАВИЛА КОНТЕНТА (СТРОГО):
    1. ОБЪЕМ СТАТЬИ: 3000 - 3500 печатных знаков. Это лонгрид.
    2. ОТ ЛИЦА РЕДАКЦИИ: Никаких "Я" или "Мы". Только безличные обороты или "Редакция Первого Туристического".
    3. НИКАКОГО MARKDOWN: В полях body КАТЕГОРИЧЕСКИ запрещены ##, **, __, *. Текст должен быть абсолютно чистым. 
    4. СТРУКТУРА: Статья должна состоять из Заголовка и 4-5 секций (sections). Каждая секция имеет заголовок (heading).
    5. ХЕШТЕГИ: 
       - Поле hashtags: просто слова через запятую (туризм, россия, отдых).
       - Посты в соцсети: слова С решеткой (#туризм, #россия).
    6. СОЦСЕТИ: Посты для TG и VK должны быть развернутыми, с интригой. Если текст получается слишком длинным, добавь фразу: "Полная версия аналитики — на нашем сайте."

    ВЕРНИ JSON:
    {
      "siteArticle": { 
        "headline": "Заголовок статьи", 
        "sections": [
           { "heading": "Подзаголовок 1", "body": "Длинный текст раздела..." },
           { "heading": "Подзаголовок 2", "body": "Еще более длинный текст..." }
        ],
        "hashtags": "туризм, рф, поездки" 
      },
      "telegramPost": { "content": "Расширенный пост с #тегами" },
      "vkPost": { "content": "Расширенный пост с #тегами" },
      "imagePrompts": ["high-end photo prompt 1", "high-end photo prompt 2", "high-end photo prompt 3"],
      "metaDescription": "SEO описание"
    }
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: `Тема: ${newsItem.title}. Факты: ${newsItem.summary}. Напиши статью объемом 3000-3500 знаков. Раздели на секции. Текст должен быть чистым без спецсимволов.`,
      config: { 
        tools: [{ googleSearch: {} }],
        systemInstruction, 
        responseMimeType: "application/json" 
      }
    });

    const parsed = JSON.parse(cleanJsonResponse(response.text || ""));
    return { newsId: newsItem.id, ...parsed };
  } catch (error) {
    console.error("Article generation error", error);
    throw new Error("Ошибка генерации статьи.");
  }
};

export const generateImage = async (prompt: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: `High-end professional photography, travel scene, 8k, cinematic: ${prompt} --no illustration, text` }] },
      config: { imageConfig: { aspectRatio: "16:9" } }
    });
    const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
    return part ? `data:image/png;base64,${part.inlineData.data}` : "";
  } catch { return ""; }
};

export const generateImagesForArticle = async (prompts: string[]): Promise<string[]> => {
  const images: string[] = [];
  for (const p of prompts.slice(0, 3)) {
    const img = await generateImage(p);
    if (img) images.push(img);
    await new Promise(r => setTimeout(r, 2000)); 
  }
  while(images.length < 3) images.push(""); 
  return images;
};

import React, { useState, useEffect } from 'react';
import { GeneratedContentPack, PublishingConfig, ArticleSection } from '../types';
import { publishToTelegram, publishToVK, publishToWordPress } from '../services/publishingService';

interface ResultViewerProps {
  pack: GeneratedContentPack;
  pubConfig: PublishingConfig;
}

export const ResultViewer: React.FC<ResultViewerProps> = ({ pack, pubConfig }) => {
  const [activeTab, setActiveTab] = useState<'site' | 'telegram' | 'vk' | 'prompts'>('site');
  const [isEditing, setIsEditing] = useState(false);

  const [headline, setHeadline] = useState(pack.siteArticle?.headline || '');
  const [sections, setSections] = useState<ArticleSection[]>(pack.siteArticle?.sections || []);
  const [hashtags, setHashtags] = useState(pack.siteArticle?.hashtags || '');
  const [metaDesc, setMetaDesc] = useState(pack.metaDescription || '');
  const [tgText, setTgText] = useState(pack.telegramPost?.content || '');
  const [vkText, setVkText] = useState(pack.vkPost?.content || '');

  const [publishing, setPublishing] = useState<string | null>(null);
  const [pubStatus, setPubStatus] = useState<{ [key: string]: { success: boolean; msg: string } }>({});
  const [scheduleDate, setScheduleDate] = useState<string>('');

  useEffect(() => {
    setHeadline(pack.siteArticle?.headline || '');
    setSections(pack.siteArticle?.sections || []);
    setHashtags(pack.siteArticle?.hashtags || '');
    setMetaDesc(pack.metaDescription || '');
    setTgText(pack.telegramPost?.content || '');
    setVkText(pack.vkPost?.content || '');
  }, [pack]);

  const handlePublish = async (platform: 'telegram' | 'vk' | 'wp') => {
    setPublishing(platform);
    const dateObj = scheduleDate ? new Date(scheduleDate) : undefined;

    // Для WP собираем текст с HTML тегами для верстки
    const fullContent = sections.map(s => `<h3><strong>${s.heading}</strong></h3>\n<p>${s.body.replace(/\n/g, '</p><p>')}</p>`).join('\n\n');

    try {
      if (platform === 'telegram') await publishToTelegram(pubConfig, tgText, pack.generatedImages[0], dateObj);
      else if (platform === 'vk') await publishToVK(pubConfig, vkText, pack.generatedImages[0], dateObj);
      else if (platform === 'wp') await publishToWordPress(pubConfig, headline, fullContent, pack.generatedImages, hashtags, dateObj, metaDesc);

      setPubStatus(prev => ({ ...prev, [platform]: { success: true, msg: 'Запланировано/Опубликовано!' } }));
    } catch (e: any) {
      setPubStatus(prev => ({ ...prev, [platform]: { success: false, msg: e.message } }));
    } finally {
      setPublishing(null);
    }
  };

  const handleSectionChange = (index: number, field: 'heading' | 'body', value: string) => {
    const newSections = [...sections];
    newSections[index][field] = value;
    setSections(newSections);
  };

  const PublishBar = ({ platform, label }: { platform: 'wp' | 'vk' | 'telegram', label: string }) => (
    <div className="mb-6 bg-slate-50 p-4 rounded-2xl border border-slate-100 flex items-center justify-between gap-4">
      <div className="flex flex-col">
        <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">{label}</span>
        {pubStatus[platform]?.msg && <span className={`text-[10px] font-bold ${pubStatus[platform].success ? 'text-green-600' : 'text-red-600'}`}>{pubStatus[platform].msg}</span>}
      </div>
      <div className="flex items-center gap-3">
        <input 
          type="datetime-local" 
          value={scheduleDate} 
          onChange={(e) => setScheduleDate(e.target.value)} 
          className="text-[10px] border border-slate-200 rounded px-2 py-1.5 bg-white outline-none focus:ring-1 focus:ring-brand-orange" 
        />
        <button 
          onClick={() => handlePublish(platform)} 
          disabled={!!publishing} 
          className="bg-brand-orange text-white text-[10px] px-4 py-2 rounded-lg font-black uppercase hover:bg-orange-600 shadow-md shadow-orange-100 disabled:opacity-50"
        >
          {publishing === platform ? '...' : (scheduleDate ? 'Запланировать' : 'В эфир')}
        </button>
      </div>
    </div>
  );

  if (pack.error) return <div className="p-10 text-center text-red-500 font-bold">{pack.error}</div>;

  return (
    <div className="bg-white rounded-[2rem] shadow-2xl overflow-hidden border border-slate-100 flex flex-col h-full animate-fade-in mb-10">
      <div className="bg-brand-dark border-b border-white/5 p-3 flex justify-between items-center">
        <div className="flex space-x-2">
          {['site', 'telegram', 'vk', 'prompts'].map((tab) => (
            <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-4 py-2 text-[10px] font-black rounded-lg uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-brand-orange text-white shadow-lg' : 'text-slate-400 hover:text-white'}`}>
              {tab === 'site' ? 'Статья' : tab === 'telegram' ? 'TG' : tab === 'vk' ? 'VK' : 'Промпты'}
            </button>
          ))}
        </div>
        <button onClick={() => setIsEditing(!isEditing)} className={`px-4 py-2 text-[10px] font-black rounded-lg uppercase border transition-all ${isEditing ? 'bg-white text-brand-dark' : 'text-white border-white/20'}`}>
          {isEditing ? 'Сохранить' : 'Править'}
        </button>
      </div>

      <div className="p-8 overflow-y-auto flex-1 custom-scrollbar">
        {activeTab === 'site' && (
          <div className="space-y-6">
            <PublishBar platform="wp" label="WordPress Издание" />

            <article className="article-font max-w-none">
              {isEditing ? (
                <div className="space-y-4">
                  <input value={headline} onChange={e => setHeadline(e.target.value)} className="w-full p-2 border font-bold text-xl" />
                  {sections.map((s, i) => (
                    <div key={i} className="space-y-2 p-4 bg-slate-50 rounded-xl">
                      <input value={s.heading} onChange={e => handleSectionChange(i, 'heading', e.target.value)} className="w-full p-2 border font-bold" />
                      <textarea value={s.body} onChange={e => handleSectionChange(i, 'body', e.target.value)} className="w-full h-48 p-2 border" />
                    </div>
                  ))}
                  <input value={hashtags} onChange={e => setHashtags(e.target.value)} className="w-full p-2 border text-sm" placeholder="Теги через запятую" />
                </div>
              ) : (
                <>
                  <h1 className="text-4xl font-black text-brand-dark leading-tight mb-8">{headline}</h1>
                  <div className="space-y-10 text-slate-800">
                    {sections.map((section, idx) => (
                      <div key={idx} className="space-y-4">
                        {section.heading && <h2 className="text-2xl font-black text-brand-dark uppercase border-b-2 border-orange-100 pb-2">{section.heading}</h2>}
                        <div className="space-y-4">
                          {section.body.split('\n').filter(p => p.trim()).map((para, pIdx) => (
                            <p key={pIdx} className="leading-relaxed text-justify text-lg" style={{ textIndent: '2.5rem' }}>
                              {para.trim()}
                            </p>
                          ))}
                        </div>
                      </div>
                    ))}
                  </div>

                  <div className="grid grid-cols-1 gap-8 my-12">
                    {pack.generatedImages.map((img, i) => img && (
                      <img key={i} src={img} className="w-full rounded-[2rem] shadow-2xl" alt="Иллюстрация" />
                    ))}
                  </div>

                  <div className="mt-8 pt-6 border-t flex items-center gap-3">
                    <span className="text-[10px] font-black text-brand-orange uppercase">Теги:</span>
                    <p className="text-slate-500 text-[10px] font-bold uppercase tracking-wide">
                      {hashtags}
                    </p>
                  </div>
                </>
              )}
            </article>
          </div>
        )}

        {activeTab === 'telegram' && (
          <div className="max-w-md mx-auto space-y-4">
             <PublishBar platform="telegram" label="Telegram Канал" />
             <div className="bg-[#f0f2f5] p-6 rounded-3xl text-sm whitespace-pre-wrap leading-relaxed shadow-inner border border-slate-200/50 text-slate-700">
                {tgText}
             </div>
          </div>
        )}

        {activeTab === 'vk' && (
          <div className="max-w-md mx-auto space-y-4">
             <PublishBar platform="vk" label="ВКонтакте Группа" />
             <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-xl text-sm whitespace-pre-wrap leading-relaxed text-slate-700">
                {vkText}
             </div>
          </div>
        )}

        {activeTab === 'prompts' && (
          <div className="space-y-4">
            <h3 className="font-black text-brand-dark text-xs uppercase tracking-widest border-b pb-4">Задания для генерации</h3>
            {pack.imagePrompts.map((p, i) => (
              <div key={i} className="p-4 bg-slate-50 border border-slate-200 rounded-xl text-[11px] font-mono leading-relaxed relative group">
                <span className="bg-brand-orange text-white w-5 h-5 flex items-center justify-center rounded-full text-[9px] font-black absolute -top-2 -left-2">{i+1}</span>
                {p}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};
